const a=JSON.parse('{"work":{"id":"guanzi","schoolId":"legalism","title":"《管子》","genreStrategy":"argumentative","sourceNote":"版本來源自通行本及校勘附記。","chapterIds":["guanzi_ch-1","guanzi_ch-2","guanzi_ch-3","guanzi_ch-4"],"totalChars":6912},"chapters":[{"id":"guanzi_ch-1","workId":"guanzi","order":1,"title":"牧民","difficulty":4,"estimatedMinutes":10,"passageIds":["guanzi_ch-1_p-1","guanzi_ch-1_p-2","guanzi_ch-1_p-3","guanzi_ch-1_p-4","guanzi_ch-1_p-5","guanzi_ch-1_p-6","guanzi_ch-1_p-7","guanzi_ch-1_p-8","guanzi_ch-1_p-9","guanzi_ch-1_p-10"],"tags":[]},{"id":"guanzi_ch-2","workId":"guanzi","order":2,"title":"形勢","difficulty":4,"estimatedMinutes":10,"passageIds":["guanzi_ch-2_p-1","guanzi_ch-2_p-2","guanzi_ch-2_p-3","guanzi_ch-2_p-4","guanzi_ch-2_p-5","guanzi_ch-2_p-6","guanzi_ch-2_p-7","guanzi_ch-2_p-8","guanzi_ch-2_p-9"],"tags":[]},{"id":"guanzi_ch-3","workId":"guanzi","order":3,"title":"權修","difficulty":4,"estimatedMinutes":10,"passageIds":["guanzi_ch-3_p-1","guanzi_ch-3_p-2","guanzi_ch-3_p-3","guanzi_ch-3_p-4","guanzi_ch-3_p-5","guanzi_ch-3_p-6","guanzi_ch-3_p-7","guanzi_ch-3_p-8","guanzi_ch-3_p-9","guanzi_ch-3_p-10","guanzi_ch-3_p-11","guanzi_ch-3_p-12","guanzi_ch-3_p-13"],"tags":[]},{"id":"guanzi_ch-4","workId":"guanzi","order":4,"title":"立政","difficulty":4,"estimatedMinutes":10,"passageIds":["guanzi_ch-4_p-1","guanzi_ch-4_p-2","guanzi_ch-4_p-3","guanzi_ch-4_p-4","guanzi_ch-4_p-5","guanzi_ch-4_p-6","guanzi_ch-4_p-7","guanzi_ch-4_p-8","guanzi_ch-4_p-9","guanzi_ch-4_p-10","guanzi_ch-4_p-11","guanzi_ch-4_p-12","guanzi_ch-4_p-13","guanzi_ch-4_p-14","guanzi_ch-4_p-15","guanzi_ch-4_p-16","guanzi_ch-4_p-17","guanzi_ch-4_p-18","guanzi_ch-4_p-19","guanzi_ch-4_p-20"],"tags":[]}],"passages":[{"id":"guanzi_ch-1_p-1","chapterId":"guanzi_ch-1","order":1,"canonicalText":"凡有地牧民者，務在四時，守在倉廩。國多財，則遠者來，地闢舉，則民留處；倉廩實，則知禮節；衣食足，則知榮辱。上服度，則六親固。四維張，則君令行。故省刑之要，在禁微而審度。","sentenceIds":["guanzi_ch-1_p-1_s-1","guanzi_ch-1_p-1_s-2","guanzi_ch-1_p-1_s-3","guanzi_ch-1_p-1_s-4","guanzi_ch-1_p-1_s-5","guanzi_ch-1_p-1_s-6","guanzi_ch-1_p-1_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"大凡擁有國土、治理撫育萬民的執政君主，根本要務在於順應春夏秋冬四時農時，戰略防守在於充實國家糧倉倉廩！國家財富充裕，遠方的百姓就會主動前來歸附；荒地得到充分開墾，本國的百姓就會安居留守；糧倉倉廩充實豐盈，百姓就懂得講求禮節規矩；衣服糧食豐足無缺，百姓就懂得明辨光榮與恥辱！君上統治者恪守禮度法度，家族六親骨肉就能團結和睦；國家四維（禮義廉恥）全面張弛確立，君王的政令就能暢通無阻推行！所以減少刑罰的根本關鍵，在於防範微小隱患並嚴格審定法度！","analysis":"【題解與倉廩實知禮節衣食足知榮辱】本段為《管子・牧民》乃至先秦經世哲學之最著名千古名篇——管仲確立「物質基礎決定精神文明」的唯物政治經濟學定理！\\n【詞義訓詁】「牧民」：治理撫育人民；「倉廩實知禮節，衣食足知榮辱」：千古名句，司馬遷《史記・管晏列傳》全篇引用；「上服度」：統治者恪守禮度法規；「禁微而審度」：防微杜漸、嚴明制度。\\n【管子唯物政治學】管仲指出道德教化不能脫離物質生活。唯有先解決人民溫飽（倉廩實、衣食足），仁義禮節與榮辱觀念才能真正深入人心，奠定齊桓公稱霸之經濟基石。"}},{"id":"guanzi_ch-1_p-2","chapterId":"guanzi_ch-1","order":2,"canonicalText":"右國頌。故治國之要，務在積穀富民，四維既張，天下歸心。","sentenceIds":["guanzi_ch-1_p-2_s-1","guanzi_ch-1_p-2_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"以上這段是歌頌國家的篇章。所以治理國家的要點，務必在於積蓄糧食並使百姓富裕，只要禮、義、廉、恥這四維能夠伸張，天下百姓的心自然就會歸向國家。","analysis":"【訓詁與名物】「右」在古籍中常指「上文」或「以上」。「國頌」指歌頌國家治理原則的文字。「積穀富民」即積蓄糧食、使人民富足，這是管仲經濟思想的核心。「四維」指禮、義、廉、恥四種國家綱紀。「張」指伸張、弘揚。「歸心」指心悅誠服地歸順。\\n【章法與結構】此為《管子·牧民》篇中總結性質的短語。以「故」字承先啟後，點出治國的兩大支柱：物質基礎（積穀富民）與精神綱紀（四維既張）。前後對稱，簡潔有力。\\n【思想與義理】本段集中體現了管仲「衣食足而知榮辱」的唯物主義政治觀。他認為，治理國家不能僅憑空洞的道德說教，必須先解決百姓的溫飽問題。在物質生活得到保障（富民）的基礎上，再推行道德教化（張四維），如此一來，政權才能穩固，天下民心才能真正歸附。這種經世致用的思想，對後世產生了深遠影響。"}},{"id":"guanzi_ch-1_p-3","chapterId":"guanzi_ch-1","order":3,"canonicalText":"國有四維，一維絕則傾，二維絕則危，三維絕則覆，四維絕則滅。傾可正也，危可安也，覆可起也，滅不可復錯也。何謂四維？一曰禮，二曰義，三曰廉，四曰恥。禮不踰節，義不自進，廉不蔽惡，恥不從枉。故不踰節則上位安，不自進則民無巧詐，不蔽惡則行自全，不從枉則邪事不生。","sentenceIds":["guanzi_ch-1_p-3_s-1","guanzi_ch-1_p-3_s-2","guanzi_ch-1_p-3_s-3","guanzi_ch-1_p-3_s-4","guanzi_ch-1_p-3_s-5","guanzi_ch-1_p-3_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"一個國家有支撐社稷命脈的四大根本綱維（四維）：斷絕了一條綱維，國家就會發生傾斜；斷絕了兩條綱維，國家就會陷入危殆；斷絕了三條綱維，國家政權就會傾覆顛覆；四條綱維全部斷絕，國家就會徹底滅亡！傾斜了還可以扶正，危殆了還可以轉危為安，傾覆了還可以重新重建，而一旦徹底滅亡就再也無法重新建立了！什麼叫做四維呢？第一叫做禮，第二叫做義，第三叫做廉，第四叫做恥！所謂禮，是指言行絕不超越制度節度；所謂義，是指絕不妄自鑽營求進；所謂廉，是指絕不隱瞞掩蓋罪惡劣跡；所謂恥，是指絕不盲從邪曲不正之事！所以言行不逾越節度則君主上位安寧，不妄自鑽營則民風沒有巧詐，不隱瞞罪惡則品行自然保全，不盲從邪曲則奸邪之事就不會滋生！","analysis":"【題解與國之四維禮義廉恥】本段為中國倫理政治哲學最核心之奠基篇章——管仲首次提出「禮、義、廉、恥」為「國之四維」，並精闢定義其現代政治倫理內涵！\\n【詞義訓詁】「四維」：支撐大帳篷的四條巨繩，比喻國家四大支柱；「禮不踰節」：守規矩法度；「義不自進」：不搞投機鑽營；「廉不蔽惡」：清廉透明不掩惡；「恥不從枉」：明辨是非不隨波逐流。\\n【國家軟實力與制度安全】管仲將四維視為政權生死存亡的終極防線：四維不張，國乃滅亡。這是華夏文明最具原創性的政治體系安全理論。"}},{"id":"guanzi_ch-1_p-4","chapterId":"guanzi_ch-1","order":4,"canonicalText":"右四維。守國之度，在張四維；四維不張，國乃滅亡。","sentenceIds":["guanzi_ch-1_p-4_s-1","guanzi_ch-1_p-4_s-2","guanzi_ch-1_p-4_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"以上這段是關於四維的論述。守護國家政權的法度，在於伸張禮、義、廉、恥這四條綱紀；如果這四維不能伸張，國家就會走向滅亡。","analysis":"【訓詁與名物】「右四維」指上文關於四維的論述內容。「守國之度」指維持國家生存與穩定的法則、法度。「四維」即禮、義、廉、恥，管仲將其比喻為維繫國家的四根大繩。「滅亡」指國家覆滅。\\n【章法與結構】結構極其簡練，正反對比。「在張四維」為正面立論，「四維不張，國乃滅亡」為反面警告。語氣篤定，不容置疑。\\n【思想與義理】此段極度強調了道德綱紀對於國家存亡的決定性作用。雖然管仲重視經濟，但他同樣明白，如果一個社會失去了禮義廉恥的約束，縱然物質再豐富，國家也會因為內部腐敗、失去凝聚力而崩潰。這將道德提升到了國家戰略安全的高度，警示統治者必須在物質與精神兩方面雙管齊下。"}},{"id":"guanzi_ch-1_p-5","chapterId":"guanzi_ch-1","order":5,"canonicalText":"政之所興，在順民心。政之所廢，在逆民心。民惡憂勞，我佚樂之。民惡貧賤，我富貴之，民惡危墜，我存安之。民惡滅絕，我生育之。能佚樂之，則民為之憂勞。能富貴之，則民為之貧賤。能存安之，則民為之危墜。能生育之，則民為之滅絕。故刑罰不足以畏其意，殺戮不足以服其心。故刑罰繁而邪不勝，能順人心，則天下自服。","sentenceIds":["guanzi_ch-1_p-5_s-1","guanzi_ch-1_p-5_s-2","guanzi_ch-1_p-5_s-3","guanzi_ch-1_p-5_s-4","guanzi_ch-1_p-5_s-5","guanzi_ch-1_p-5_s-6","guanzi_ch-1_p-5_s-7","guanzi_ch-1_p-5_s-8","guanzi_ch-1_p-5_s-9","guanzi_ch-1_p-5_s-10","guanzi_ch-1_p-5_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"國家政令政權之所以興盛，在於順應萬民的人心向背（在順民心）；政令政權之所以廢弛敗亡，在於違逆萬民的人心向背（在逆民心）！百姓厭惡憂患勞苦，我就讓他們安逸享樂；\\n百姓厭惡貧窮低賤，我就讓他們富足顯貴；\\n百姓厭惡危險傾覆，我就讓他們安定生存；\\n百姓厭惡斷子絕孫，我就讓他們繁衍養育！統治者若能讓百姓安逸享樂，百姓就甘願為國家承擔憂患辛勞！統治者若能讓百姓富足顯貴，百姓就甘願為國家忍受貧困艱難！統治者若能讓百姓安全生存，百姓就甘願為國家赴湯蹈火直面危險！統治者若能讓百姓繁衍育子，百姓就甘願為國家視死如歸犧牲生命！所以單純依靠嚴酷刑罰不足以威懾改變百姓的內心意志，單純依靠屠殺殺戮不足以真正降服百姓的心靈！因此刑罰越繁苛而邪惡越無法遏制；唯有真正順應天下民心，天下百姓自然由衷臣服！","analysis":"【題解與政之所興在順民心四順哲學】本段為管子民本主義政治學之巔峯篇章——提出「政之所興在順民心、政之所廢在逆民心」與「四順互惠政治契約」！\\n【詞義訓詁】「民惡憂勞我佚樂之」：精準把握人民趨利避害之天性；「能佚樂之則民為之憂勞」：權利與義務之動態平衡；「刑罰不足以服其心」：反對純粹法家恐怖統治。\\n【現代政治合法性理論】管仲深刻指出統治的本質是一場雙向奔赴的政治契約：政府先給予人民安全、繁衍、財富與安樂，人民才會在國家危難時甘願奉獻勞動、財產乃至生命。"}},{"id":"guanzi_ch-1_p-6","chapterId":"guanzi_ch-1","order":6,"canonicalText":"右四順。順民之情，修政之本；違民所欲，雖威必廢。","sentenceIds":["guanzi_ch-1_p-6_s-1","guanzi_ch-1_p-6_s-2","guanzi_ch-1_p-6_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"以上這段是關於四順的論述。順應百姓的性情與心願，是修明政治的根本；如果違背了百姓的欲望與需求，即使統治者再有威嚴，其政權也必定會被廢棄或推翻。","analysis":"【訓詁與名物】「右四順」指上文提到的順應民心的四個方面（如順其生、順其富等）。「民之情」指人民的真實情感與需求。「本」即根本。「所欲」指人民所期盼的事物。「威」指統治者的威權、武力。「廢」指廢除、敗亡。\\n【章法與結構】採用「順...」與「違...」的正反對比句式。「順民之情」帶來「修政之本」的良性結果，「違民所欲」則導致「雖威必廢」的惡果，邏輯清晰，對照強烈。\\n【思想與義理】這段話蘊含了深刻的民本思想。管仲指出，政治的基礎不在於君王的威權，而在於是否能順應民心。人民有追求生存、富裕、安定的本能欲望，順應這些欲望去制定政策，政治自然清明；反之，若恃強凌弱、橫徵暴斂，違背了民意，縱使手握重兵，政權也將難以維持。這與後世儒家的「得民心者得天下」有異曲同工之妙。"}},{"id":"guanzi_ch-1_p-7","chapterId":"guanzi_ch-1","order":7,"canonicalText":"錯國於不傾之地，積於不涸之倉，藏於不竭之府，下令於流水之原，使民於不爭之官，明必死之路，開必生之門。毋使民爭，則民自安；毋使民巧，則民自實。此之謂士經也。","sentenceIds":["guanzi_ch-1_p-7_s-1","guanzi_ch-1_p-7_s-2","guanzi_ch-1_p-7_s-3","guanzi_ch-1_p-7_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"將國家政權安立在不可傾斜的穩固基石之上（錯國於不傾之地），將物資儲備積蓄在永不乾涸的國家糧倉之中，將財政財富儲藏在永不枯竭的充盈府庫之中；把頒佈政令建立在如同流水順流而下般順應民心的源頭上，任用百姓在職責分明無所爭奪的崗位之中；向全軍明示違犯軍令必定處死的死路，向天下廣開立功受賞必定享福的生門！不讓百姓陷入無序惡性爭奪，百姓自然安居樂業；不讓社會風氣滋長投機取巧，百姓自然淳厚務實！這就稱之為士人治國的根本經典（士經）！","analysis":"【題解與背景】\\n本段選自《管子》〈牧民〉第 7 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「錯國於不傾之地積於不涸之倉藏於不竭之府下……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「錯」、「國」、「於」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《管子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：guanzi_ch-1_p-7）。"}},{"id":"guanzi_ch-1_p-8","chapterId":"guanzi_ch-1","order":8,"canonicalText":"右士經。審立制度，安國固本；明示死生，天下莫爭。","sentenceIds":["guanzi_ch-1_p-8_s-1","guanzi_ch-1_p-8_s-2","guanzi_ch-1_p-8_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"以上這段是關於士經（士人的行為準則）的論述。審慎地建立各項法規與制度，就能使國家安定、鞏固政權的根本；明確地向天下展示獎勵（生）與懲罰（死）的標準，天下人就沒有什麼好爭論與違抗的了。","analysis":"【訓詁與名物】「右士經」指上文關於規範士人與官員行為的內容。「審」指審慎、周密。「制度」指法律、規章。「固本」指鞏固國家的根基。「死生」在此處引申為生殺大權、獎懲標準或利害關係。「莫爭」指沒有爭議、不再違抗。\\n【章法與結構】為兩組工整的四字短句。「審立制度」對「明示死生」，皆為統治者的作為；「安國固本」對「天下莫爭」，皆為達到的治國效果。言簡意賅，具有濃厚的法家色彩。\\n【思想與義理】本段體現了《管子》中法家「明法慎罰」的思想成分。強調治國不能僅靠道德教化，還必須有嚴密客觀的制度作為保障。只要法令制度制定得審慎合理，並且將賞罰的標準公開透明地詔告天下，讓百姓明白何者當賞（生）、何者當罰（死），社會自然就會建立起穩定的秩序，從而消弭紛爭與動亂。"}},{"id":"guanzi_ch-1_p-9","chapterId":"guanzi_ch-1","order":9,"canonicalText":"以家為鄉，鄉不可為也。以鄉為國，國不可為也。以國為天下，天下不可為也。以家為家，以鄉為鄉，以國為國，以天下為天下。審其分，明其職，各安其位，則六親固而五法行矣。","sentenceIds":["guanzi_ch-1_p-9_s-1","guanzi_ch-1_p-9_s-2","guanzi_ch-1_p-9_s-3","guanzi_ch-1_p-9_s-4","guanzi_ch-1_p-9_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"如果用管理一個小家庭的狹隘方式去治理整個鄉里，鄉里是絕對治理不好的；如果用治理鄉里的簡單方式去治理整個諸侯國家，國家是絕對治理不好的；如果用治理單一國家的方式去治理整個天下，天下是絕對無法治理太平的！必須用治理家庭的倫理治理家庭，用治理鄉里的規則治理鄉里，用治理國家的法度治理國家，用統攬天下的宏大視野治理天下！審度各自的層級界限，明確各自的職責權限，使各個階層各安其位，那麼家庭六親骨肉自然穩固和睦，國家五大根本法度自然順利推行了！","analysis":"【題解與以家為家以天下為天下之層級治理】管仲提出層級治理與尺度效應（Scale Effect）理論——反對將微觀家庭倫理簡單套用於宏觀國家與天下治理，強調各層級有其專屬法度！\\n【詞義訓詁】「以家為家，以天下為天下」：各自依照特定組織規模與治理規律推行政務；「審其分明其職」：分清權責邊界；「六親固五法行」：微觀家庭和睦與宏觀五大法度並行不悖。\\n【公共治理哲學】管仲打破了儒家將「修身齊家」無限線性放大為「治國平天下」的樸素倫理推演，指出天下治理需要專門的宏觀政治制度與經濟法則。"}},{"id":"guanzi_ch-1_p-10","chapterId":"guanzi_ch-1","order":10,"canonicalText":"右六親五法。修身齊家，各守其分；治國平天下，法度明備。此牧民之終始也。","sentenceIds":["guanzi_ch-1_p-10_s-1","guanzi_ch-1_p-10_s-2","guanzi_ch-1_p-10_s-3","guanzi_ch-1_p-10_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"以上所述就是關於六親的倫理與五種治國的法度。個人修養身心、管理好家庭，每個人都應該恪守自己的本分；要治理好國家乃至平定天下，就必須使國家的法度嚴明且完備。這些就是治理人民的根本原則與始終不變的道理。","analysis":"【訓詁與名物】「右」指上文、以上。「六親」通常指父、母、兄、弟、妻、子，泛指家族倫理。「五法」指治國的五種法度規範。「牧民」即治理人民，古人視官吏治民如牧羊，故稱牧民。「終始」指事情的始終、根本之道。【章法與結構】此段為《管子·牧民》篇的總結性文字。「右六親五法」總括前文；接著分為兩個層次：「修身齊家」對應「各守其分」，「治國平天下」對應「法度明備」。從小到大，由內而外，最後以「此牧民之終始也」作結，結構嚴謹，邏輯層次分明。【思想與義理】這段文字體現了《管子》將儒家的倫理道德（修身齊家、各守其分）與法家的法治思想（治國平天下、法度明備）相結合的政治特點。它表明，成功的「牧民」之道，既需要建立在家族倫理與個人修養的基礎上，更離不開國家層面嚴明完備的法制。這展現了齊國學派德法並用、王霸兼雜的治國理念。"}},{"id":"guanzi_ch-2_p-1","chapterId":"guanzi_ch-2","order":1,"canonicalText":"山高而不崩，則祈羊至矣；淵深而不涸，則沈玉極矣，天不變其常，地不易其則，春秋冬夏，不更其節，古今一也。故為人君者，守常而不妄，則萬民自化矣。","sentenceIds":["guanzi_ch-2_p-1_s-1","guanzi_ch-2_p-1_s-2","guanzi_ch-2_p-1_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"高山巍峨聳立而永不坍塌，前來祈福祭祀的太牢羊牲就會絡繹不絕而至；深淵浩瀚深沉而永不乾涸，投入水底祭祀的水神美玉就會極其豐厚充足；蒼天不改變其日月運行的常規，大地不更改其承載萬物的法則，春生、夏長、秋收、冬藏四時節氣永不混亂更替，從古至今都是同一個客觀規律！所以身為統治天下的君主，只要恪守客觀常道而不盲目妄為胡折騰，那麼天下萬民自然就能順應化育、各得其所了！","analysis":"【題解與山高不崩淵深不涸守常不妄】本段為《管子・形勢》開篇，以山高淵深天地四時之永恆常道為喻，論述君主必須「守常不妄」、維護制度連續性與可預期性。\\n【詞義訓詁】「祈羊至」：祭山祈福之牲禮；「沈玉極」：古人祭水神沉美玉於深淵；「守常而不妄」：遵循客觀規律與法度，不朝令夕改、不胡亂折騰。\\n【制度穩定性與預期管理】大自然因其規律恆定而贏得萬物信賴；國家政權亦然，唯有保持法度與政策的長期穩定，市場與百姓才能建立穩定預期。"}},{"id":"guanzi_ch-2_p-2","chapterId":"guanzi_ch-2","order":2,"canonicalText":"銜命者，君之尊也。受辭者，名之鉉也。上無事，則民自試。抱蜀不言，而廟堂既修。鴻鵠鏘鏘，唯民歌之。明君垂拱，而天下自治。","sentenceIds":["guanzi_ch-2_p-2_s-1","guanzi_ch-2_p-2_s-2","guanzi_ch-2_p-2_s-3","guanzi_ch-2_p-2_s-4","guanzi_ch-2_p-2_s-5","guanzi_ch-2_p-2_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"奉命出使執行使命的使節，代表著君王的至高尊嚴；接受君王任命辭令的重臣，是維繫國家名分綱紀的關鍵樞紐（名之鉉）。君王在上清靜無為不隨意幹擾，民間百姓自然會競相施展各自的才智本領（民自試）！君王如抱持木鐸神器般沉靜不發妄言，而朝廷廟堂的綱紀政風早已修明整肅！如同鴻鵠天鵝在雲霄清鳴鏘鏘，普天下百姓由衷歡唱讚頌之歌。英明的君王垂衣拱手而天下自然達到大治太平！","analysis":"【題解與上無事民自試與垂拱而治】管仲融匯黃老道家精髓，論述君主應當抓大放小、清靜無為，為民間社會自我發展釋放空間。\\n【詞義訓詁】「名之鉉」：鉉，鼎耳之槓，比喻維繫名分體制之樞紐；「民自試」：百姓各展其能、自主創新；「抱蜀不言」：抱持法度沉靜不擾民。\\n【激發市場與社會活力】君主不事事包辦幹預，而是確立規則後「無事以待」，讓民間自主發揮創造力（民自試），達到無為而無不為之至高境界。"}},{"id":"guanzi_ch-2_p-3","chapterId":"guanzi_ch-2","order":3,"canonicalText":"平原之隰，奚有於高？大山之隈，奚有於深？訾讆之人，勿與任大。譕臣者可以遠舉。顧憂者可與致道。任賢使能，必因其材也。","sentenceIds":["guanzi_ch-2_p-3_s-1","guanzi_ch-2_p-3_s-2","guanzi_ch-2_p-3_s-3","guanzi_ch-2_p-3_s-4","guanzi_ch-2_p-3_s-5","guanzi_ch-2_p-3_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"平坦開闊的低窪平原，哪裡會有高聳的山丘？巍峨大山的深邃山灣，哪裡會有淺顯的平地？凡是習慣於詆毀中傷、阿諛奉承的小人（訾讆之人），絕對不可委託託付他們承擔國家重大重任！善於深謀遠慮的大臣（譕臣）可以委以重任經略遠大功業；心懷憂患意識、顧念蒼生疾苦的賢者（顧憂者）可以與他們共同成就治國大道！任用賢才差遣能人，必須嚴格依據其真實品行才幹來因材適用！","analysis":"【題解與辨察小人與任用謀臣顧憂者】本段論述識人用人之道：遠離詆毀逢迎之小人（訾讆），重用深謀遠慮之謀臣（譕臣）與心懷天下之憂患之士（顧憂者）。\\n【詞義訓詁】「隰」：低濕平地；「隈」：山灣深處；「訾讆」：訾，詆毀；讆，音衛，虛妄阿諛；「譕臣」：譕通謀，足智多謀之臣；「顧憂者」：居安思危、先天下之憂而憂之士。\\n【知人善任原則】用人如量器：不可讓逢迎宵小掌大權，唯有重用具備深沉大略與道德憂患意識的骨幹，國家事業才能長治久安。"}},{"id":"guanzi_ch-2_p-4","chapterId":"guanzi_ch-2","order":4,"canonicalText":"必得之事，不足賴也；必諾之言，不足信也。小謹者不大立，訾食者不肥體；有無棄之言者，必參於天地。察言觀行，不可不慎。","sentenceIds":["guanzi_ch-2_p-4_s-1","guanzi_ch-2_p-4_s-2","guanzi_ch-2_p-4_s-3","guanzi_ch-2_p-4_s-4","guanzi_ch-2_p-4_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"聲稱必定能夠輕易辦成的事端，往往最靠不住；輕易滿口答應許諾的言辭，往往最不足以採信！過於拘泥於細枝末節的小謹小慎之人，難以建立宏大偉業；挑肥揀瘦、挑剔飲食的人，難以長成魁梧壯碩的體魄！真正具有永不被歷史拋棄的真理之言，必定能夠與天地宇宙的客觀規律相互印證參驗！審察言論、觀察行動，君主不可不極度審慎！","analysis":"【題解與背景】\\n本段選自《管子》〈形勢〉第 14 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「必得之事不足賴也必諾之言不足信也小謹者不……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「必」、「得」、「之」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《管子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：guanzi_ch-2_p-4）。"}},{"id":"guanzi_ch-2_p-5","chapterId":"guanzi_ch-2","order":5,"canonicalText":"怠倦者不及，無廣者疑神，神者在內，不及者在門，在內者將假，在門者將待。曙戒勿怠，後稚逢殃。早作夜思，乃成大業。","sentenceIds":["guanzi_ch-2_p-5_s-1","guanzi_ch-2_p-5_s-2","guanzi_ch-2_p-5_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"怠惰倦怠的人永遠趕不上歷史前進的腳步，胸懷狹隘不廣大的人往往對高深的智謀神術心生猜疑！真正通曉神機妙算的智者早已在內室深處決策定計（神者在內），而落後遲鈍的人還在宮門之外徘徊張望（不及者在門）！身居內室的智者即將從容推行大業，徘徊門外的人只能被動等待命運裁決！清晨破曉之時就當警醒戒勉自己切莫懈怠偷安，拖延落後稚鈍之人必將遭遇滅頂災殃！清晨早起勞作、深夜深思熟慮，才能成就千秋不朽之偉業！","analysis":"【題解與曙戒勿怠與早作夜思成大業】本段以生動形象的「在內（運籌帷幄）」與「在門（被動落後）」對比，警示統治者勤政戒怠、把握歷史先機。\\n【詞義訓詁】「無廣者」：心胸狹隘缺乏格局之人；「神者在內」：智慧深藏於幕後決策樞紐；「曙戒勿怠」：黎明破曉即戒備勤勉；「後稚逢殃」：落後愚鈍必遭淘汰。\\n【時間管理與先發優勢】歷史機遇稍縱即逝。唯有起跑在前、夙夜在公的先鋒者才能掌握戰略主動權；消極懈怠者終將被時代洪流無情淘汰。"}},{"id":"guanzi_ch-2_p-6","chapterId":"guanzi_ch-2","order":6,"canonicalText":"道之所言者一也，而用之者異。有聞道而好為家者，一家之人也；有聞道而好為鄉者，一鄉之人也；有聞道而好為國者，一國之人也；有聞道而好為天下者，天下之人也。器量不同，所成各殊。","sentenceIds":["guanzi_ch-2_p-6_s-1","guanzi_ch-2_p-6_s-2","guanzi_ch-2_p-6_s-3","guanzi_ch-2_p-6_s-4","guanzi_ch-2_p-6_s-5","guanzi_ch-2_p-6_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"天地大道所闡發的真理本質上是同一貫通的（道之所言者一也），然而運用大道的人其格局器量卻各不相同！有的人聽聞了大道而熱衷於經營自己的小家庭，他充其量不過是一個持家之人；有的人聽聞了大道而熱衷於治理好自己的鄉里，他充其量不過是一個鄉里之才；有的人聽聞了大道而熱衷於治理好自己的諸侯國家，他是一國的治國棟樑；有的人聽聞了大道而立志於兼濟全天下蒼生，他才是胸懷天下的至聖領袖！個人的格局器量不同，最終成就的事業功績也就各自天差地別！","analysis":"【題解與聞道之用與四種格局器量】管仲系統劃分人類格局器量的四個維度：持家者（家庭器量）、治鄉者（鄉里器量）、治國者（國家器量）、安天下者（天下格局）！\\n【詞義訓詁】「道之所言者一也」：真理本源合一；「天下之人」：以天下為己任之至高政治家；「器量不同」：格局決定結局。\\n【領袖格局論】同一個理論工具，在不同胸懷的人手中發揮的能量完全不同。成大事者必須跳出狹隘私利，將視野拓展至全天下蒼生福祉。"}},{"id":"guanzi_ch-2_p-7","chapterId":"guanzi_ch-2","order":7,"canonicalText":"生棟覆屋。怨怒不及；弱子下瓦，慈母操箠。天道之極，遠者自親。人事之起，近親造怨。萬物之於人也，知其情者能御之。","sentenceIds":["guanzi_ch-2_p-7_s-1","guanzi_ch-2_p-7_s-2","guanzi_ch-2_p-7_s-3","guanzi_ch-2_p-7_s-4","guanzi_ch-2_p-7_s-5","guanzi_ch-2_p-7_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"新長成的粗木頭被用來做棟梁蓋房屋，如果房子倒塌壓到了人，人們的怨怒也不會怪罪到木頭上；但如果是年幼的孩子不小心從屋頂上弄落了瓦片，即使是慈愛的母親也會拿起竹杖來責打他。天道的極致規律是，關係疏遠的反而會自然親近；而人際關係的發展往往是，越是親近的人之間越容易產生怨恨。宇宙萬物對於人來說，只有懂得它們真實性情與規律的人，才能夠駕馭和控制它們。","analysis":"【訓詁與名物】「生棟覆屋」指用長成的木材做棟梁蓋屋頂。「下瓦」指弄落瓦片。「箠」音垂，指竹杖、馬鞭，此處指責打的工具。「天道」指自然的規律。「人事」指人類社會的人情世故。「御」指駕馭、控制。【章法與結構】此段運用了極其精妙的對比與比喻。前半段以「生棟覆屋」與「弱子下瓦」作對比，說明怨恨的產生往往源於人際關係的親疏與期望值。接著將「天道」與「人事」進行哲理上的對比（遠者自親 vs 近親造怨）。最後得出「知其情者能御之」的結論，由現象升華為普遍的哲學真理。【思想與義理】此句深刻揭示了人情心理與自然規律的微妙差異。因為人們對無生命的木頭沒有情感期望，所以不會怨恨；而對親近的「弱子」有期望與責任，所以會責打。這說明世間恩怨往往產生於關係密切者之間。作者藉此告誡統治者，治國理政必須洞察人情世故與萬物之理（知其情），才能超越情感的羈絆，達到「御之」的最高境界。"}},{"id":"guanzi_ch-2_p-8","chapterId":"guanzi_ch-2","order":8,"canonicalText":"烏鳥之狡，雖善不親。不重之結，雖固必解；道之用也，貴其重也。毋與不可，毋彊不能，毋告不知；與不可，強不能，告不知，謂之勞而無功。","sentenceIds":["guanzi_ch-2_p-8_s-1","guanzi_ch-2_p-8_s-2","guanzi_ch-2_p-8_s-3","guanzi_ch-2_p-8_s-4","guanzi_ch-2_p-8_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"烏鴉野鳥生性狡黠多疑，縱然你對它再友善撫慰它也不會真正親近依戀；不夠牢固的單層繩結，縱然當下看似繫得很緊也終究必定會鬆脫解開；推行大道的運用，最寶貴的在於其厚重扎實、不可動搖！切莫把重任託付給不可託付之人，切莫強求根本無能力的人去辦難事，切莫把高深大道告訴毫無領悟力的愚昧之輩！把重任給不可託之人、強求無能之人、說教無知之人，這就稱之為白白耗費精力而勞而無功！","analysis":"【題解與背景】\\n本段選自《管子》〈形勢〉第 18 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「烏鳥之狡雖善不親不重之結雖固必解道之用也……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「烏」、「鳥」、「之」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《管子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：guanzi_ch-2_p-8）。"}},{"id":"guanzi_ch-2_p-9","chapterId":"guanzi_ch-2","order":9,"canonicalText":"日月不明，天不易也；山高而不見，地不易也。言而不可復者，君不言也；行而不可再者，君不行也。凡言必信，凡行必果，此明君之大節也。","sentenceIds":["guanzi_ch-2_p-9_s-1","guanzi_ch-2_p-9_s-2","guanzi_ch-2_p-9_s-3","guanzi_ch-2_p-9_s-4","guanzi_ch-2_p-9_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"日月縱然偶爾被烏雲遮蔽失去光明，蒼天日月運行的規律卻絲毫未曾改變；崇山縱然被濃霧籠罩看不清晰，大地厚載萬物的法則卻絲毫未曾動搖！說出口卻無法反覆兌現踐行的言辭，英明的君主絕不輕易說出口；推行下去卻無法持久延續重復的政令行動，英明的君主絕不輕易推行！大凡說出的話必定信實兌現，大凡推行的政令必定堅決貫徹結果，這正是英明君王立身治國的最崇高大節！","analysis":"【題解與全篇終章凡言必信凡行必果】本段為《管子・形勢》終篇，以天地日月山川為喻，論述君王言行必須「言必信、行必果」、絕不說無法兌現之空話（言不可復者君不言）。\\n【詞義訓詁】「言不可復」：復，踐行兌現；無法兌現之承諾；「行不可再」：不可持續之政令；「明君之大節」：君王立信於天下之最高品格。\\n【政治信用基石】統治者的言論與政令是國家公信力的命脈。不輕易許諾、一旦許諾必貫徹到底，方能樹立不可動搖的國家法治威嚴。"}},{"id":"guanzi_ch-3_p-1","chapterId":"guanzi_ch-3","order":1,"canonicalText":"萬乘之國，兵不可以無主，土地博大，野不可以無吏，百姓殷眾，官不可以無長，操民之命，朝不可以無政。政者，國之綱也。","sentenceIds":["guanzi_ch-3_p-1_s-1","guanzi_ch-3_p-1_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"擁有一萬輛兵車的大國，軍隊不可以沒有統帥；國家土地廣闊遼大，地方上不可以沒有管理政務的官吏；國內百姓數量眾多，各級官署不可以沒有長官；要掌握和決定民眾的命運，朝廷就不可以沒有統一的政令。所謂政令，就是治理國家的根本綱領。","analysis":"【訓詁與名物】「萬乘之國」指擁有一萬輛兵車的國家，代指大國、強國。「主」指統帥、將領。「野」指都城之外的廣大鄉野地區。「吏」指地方官吏。「殷眾」指富裕且人口眾多。「長」指官署的首長。「操民之命」指掌握民眾的生死與命運。「綱」指漁網上的總繩，比喻事物的根本部分。【章法與結構】此段採用了氣勢磅礴的排比句式。從「兵」、「野」、「官」到「朝」，從軍事、地方、官僚體繫到中央朝廷，層層推進，反覆強調「不可以無……」。最後以「政者，國之綱也」這句斬釘截鐵的判斷句作總結，提綱挈領，極具震撼力。【思想與義理】此段話體現了《管子》高度重視國家組織與行政管理的法家思想。它指出，一個大國要維持運轉，必須建立嚴密的官僚體系與軍事統帥機制，而這一切的核心都在於中央朝廷的「政」（政令與法度）。「政」就像漁網的總繩，只有抓住這個根本，纔能有效地控制國家與民眾。這反映了春秋戰國時期中央集權思想的興起。"}},{"id":"guanzi_ch-3_p-2","chapterId":"guanzi_ch-3","order":2,"canonicalText":"地博而國貧者，野不闢也，民眾而兵弱者，民無取也。故末產不禁，則野不闢。賞罰不信，則民無取。故務本禁末，信賞必罰，富國強兵之道也。","sentenceIds":["guanzi_ch-3_p-2_s-1","guanzi_ch-3_p-2_s-2","guanzi_ch-3_p-2_s-3","guanzi_ch-3_p-2_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"國家土地廣大卻依然貧窮的原因，是因為荒野的土地沒有被開墾；國家人口眾多但軍隊卻很虛弱的原因，是因為民眾沒有勇於作戰進取的精神。所以，如果不禁止工商業等非農業的生產，荒野就無法被開墾；如果賞賜與懲罰不誠實可信，民眾就不會去爭取立功。因此，致力於農業生產而抑制工商業，做到賞罰分明且必定兌現，這才是使國家富裕、軍隊強大的根本方法。","analysis":"【訓詁與名物】「地博」指土地廣大。「野不闢」指荒地沒有被開墾。「民無取」指民眾沒有進取、立功的心態。「末產」古人以農業為本，工商業為末，末產指工商業。「務本禁末」即重農抑商。「信賞必罰」指賞罰誠實可信，必定執行。【章法與結構】此段邏輯推理極為嚴密。首先提出兩個矛盾現象（地博國貧、民眾兵弱）並點出原因（野不闢、民無取）。接著分析產生這兩個原因的根源（末產不禁、賞罰不信）。最後得出解決方案與結論（務本禁末，信賞必罰，富國強兵之道也）。環環相扣，極具說服力。【思想與義理】此段是中國古代「富國強兵」與「重農抑商」思想的經典表述。《管子》認為，國家的富強建立在強大的農業基礎（務本）與嚴明的法紀（信賞必罰）之上。工商業（末產）會分散勞動力，導致農業衰退；而賞罰不分明則會使軍隊失去戰鬥力。這種思想深刻影響了後來商鞅變法及整個中國封建社會的經濟與軍事政策。"}},{"id":"guanzi_ch-3_p-3","chapterId":"guanzi_ch-3","order":3,"canonicalText":"地闢而國貧者，舟輿飾，臺榭廣也。賞罰信而兵弱者，輕用眾，使民勞也。舟車飾，臺榭廣，則賦斂厚，民怨上；輕用眾，使民勞，則兵疲極，士不用。故節用愛民，戰陣乃強。","sentenceIds":["guanzi_ch-3_p-3_s-1","guanzi_ch-3_p-3_s-2","guanzi_ch-3_p-3_s-3","guanzi_ch-3_p-3_s-4","guanzi_ch-3_p-3_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"荒地已經開墾而國家財政依然貧困的，是因為統治者過度裝飾華麗的舟船車駕、大肆修建奢靡的高臺樓榭（臺榭廣）；賞罰分明而軍隊戰鬥力依然衰弱的，是因為將帥輕率調動大軍、使廣大士兵勞役過度疲憊不堪！舟車過度奢華裝飾、宮室臺榭大興土木，國家就必定會加重苛捐雜稅剝削，導致萬民怨恨君上；輕率盲目調動部隊、使百姓疲於奔命，軍隊將士就會精疲力竭，臨陣之際士兵就再也不肯奮勇效命了！所以唯有節制財政開支、深切愛護體恤百姓，軍隊在戰場上才能真正無敵強大！","analysis":"【題解與奢靡勞民導致地闢國貧兵弱】管仲揭示即使開墾土地、確立賞罰，若統治者陷入奢靡享樂（舟輿飾臺榭廣）與窮兵黷武（輕用眾），依然會導致國家崩潰！\\n【詞義訓詁】「臺榭廣」：大興土木修建宮殿景觀；「輕用眾」：輕易發動戰爭折騰部隊；「節用愛民」：勤儉節約、愛惜民力。\\n【反奢靡與可持續發展】國力的積累需要漫長時間，而奢靡浪費與頻繁軍事冒險能在短時間內耗盡國庫與民力。剋制統治階級的消費慾望是保全戰鬥力的關鍵。"}},{"id":"guanzi_ch-3_p-4","chapterId":"guanzi_ch-3","order":4,"canonicalText":"欲為天下者，必重用其國，欲為其國者，必重用其民，欲為其民者，必重盡其民力。無以畜之，則往而不可復也。故養之以德，用之以時，蓄之以富，乃可長保天下。","sentenceIds":["guanzi_ch-3_p-4_s-1","guanzi_ch-3_p-4_s-2","guanzi_ch-3_p-4_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"想要統治天下的人，必須高度重視並利用好自己的國家；想要治理好自己國家的人，必須高度重視並利用好自己的民眾；想要為民眾謀福利（或治理民眾）的人，必須充分發揮與使用民眾的力量。但是，如果沒有物質財富來蓄養他們，民眾一旦流失離開就無法再回來了。所以，要用道德來教養他們，要在不違背農時的情況下使用他們，要用充足的財富來蓄養他們，這樣才能夠長久地保住天下的統治權。","analysis":"【訓詁與名物】「為天下」指統治天下。「重用」指高度重視並加以利用。「盡其民力」指充分發揮民眾的勞動力與創造力。「畜」同「蓄」，指蓄養、積聚財富來養育。「往而不可復」指民眾流亡他鄉不再回來。「用之以時」指徵調民力時不違背農時，避開農忙季節。【章法與結構】此段前半部分運用了頂真（聯珠）的修辭手法，「欲為天下者，必重用其國；欲為其國者，必重用其民；欲為其民者，必重盡其民力」，層層遞進，將天下、國家、民眾緊密聯繫起來。後半部分則從反面警告，並提出正面的具體措施（養之以德，用之以時，蓄之以富），首尾呼應，說理透徹。【思想與義理】此段話體現了《管子》極具現實主義色彩的民本思想。它承認統治者需要「盡其民力」，但同時深刻指出，要使用民力，前提必須是愛惜民力與蓄養民眾。將道德教化（德）、尊重規律（時）與物質保障（富）結合起來，這是一種將儒家仁政與法家功利主義完美結合的治國方略，為後世的「王霸道雜之」提供了理論依據。"}},{"id":"guanzi_ch-3_p-5","chapterId":"guanzi_ch-3","order":5,"canonicalText":"見其可也，喜之有徵。見其不可也，惡之有刑。賞罰信於其所見，雖其所不見，其敢為之乎？見其可也，喜之無徵；見其不可也，惡之無刑。賞罰不信於其所見，雖其所不見，其敢善之乎？故賞罰之信，治亂之分也。","sentenceIds":["guanzi_ch-3_p-5_s-1","guanzi_ch-3_p-5_s-2","guanzi_ch-3_p-5_s-3","guanzi_ch-3_p-5_s-4","guanzi_ch-3_p-5_s-5","guanzi_ch-3_p-5_s-6","guanzi_ch-3_p-5_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"看見臣民立下符合法度的善行善政，君上欣喜獎賞必定有實質的爵祿信物予以表彰（喜之有徵）；看見臣民做出違犯法度的惡行罪錯，君上厭惡懲戒必定有嚴格的法律刑罰予以處分（惡之有刑）！賞賜與懲罰在君王親眼所見之事上做到絕對信實公允，那麼即便在君王看不見的隱祕之處，誰又敢違法作惡呢？反之，看見善行欣喜卻沒有實質獎賞，看見惡行厭惡卻沒有實質懲罰；賞罰在親眼所見之事上毫無信譽，那麼即便在看不見的幽暗之處，誰又會自覺行善守法呢？所以賞罰是否絕對講求信義，是國家走向大治與走向大亂的根本分水嶺！","analysis":"【題解與喜之有徵惡之有刑賞罰立信】管仲以極其嚴密的邏輯剖析「賞罰立信」對全社會道德行為的引導效應：所見有信，則不見處莫敢為非！\\n【詞義訓詁】「徵」：憑證、實質獎賞信物；「賞罰信於所見」：公開透明落實獎懲；「治亂之分」：決定國家大治大亂的關鍵分界。\\n【制度心理學之透明度】公權力的威信建立在即時、可驗證的反饋機制上（喜有徵惡有刑）。如果好人不得好報、壞人不受懲治，法律將徹底失去約束力。"}},{"id":"guanzi_ch-3_p-6","chapterId":"guanzi_ch-3","order":6,"canonicalText":"地之生財有時，民之用力有倦，而人君之慾無窮，以有時與有倦，養無窮之君，而度量不生於其間，則上下相疾，亂之原也。故明君節慾以安民。","sentenceIds":["guanzi_ch-3_p-6_s-1","guanzi_ch-3_p-6_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"大地生長繁衍各類財富物資是有四時自然節奏的（地之生財有時），百姓勞動付出體力勞役是有疲憊極限的（民之用力有倦），然而封建君王統治者的享樂慾望卻是永無窮盡的（人君之慾無窮）！用自然生長有限度的土地與體力有疲憊極限的百姓，去供養慾望永無窮盡的君王，如果在這兩者之間不能確立明確的節制度量法度，那麼統治上層與基層百姓就必然會彼此仇視怨恨（上下相疾），這正是天下大亂的根本源頭！所以英明的君王必須剋制節制自身慾望以安撫天下百姓！","analysis":"【題解與有時有倦養無窮之君之矛盾論】本段為中國古代政治哲學最震撼之歷史矛盾分析——管仲一針見血指出「有限之生產力（地有時、民有倦）」與「無限之君王貪慾（君慾無窮）」是引發階級矛盾與天下大亂的終極根源！\\n【詞義訓詁】「地之生財有時」：自然資源再生產之週期限制；「民之用力有倦」：勞動者生理與心理之承載極限；「養無窮之君」：供養統治階級無限膨脹之消費慾望；「上下相疾」：階級矛盾極度激化。\\n【政治經濟學深刻洞見】兩千六百年前的管仲已精準揭示出生產力極限與剝削無度之間的致命張力。唯有將國家徵斂嚴格限制在法定「度量」之內，社會才能避免週期性崩潰。"}},{"id":"guanzi_ch-3_p-7","chapterId":"guanzi_ch-3","order":7,"canonicalText":"地之不闢者，非吾地也。民之不牧者，非吾民也。凡牧民者，以其所積者食之，不可不審也。其積多者其國富，其積少者其國貧。故務農積穀，富民之本也。","sentenceIds":["guanzi_ch-3_p-7_s-1","guanzi_ch-3_p-7_s-2","guanzi_ch-3_p-7_s-3","guanzi_ch-3_p-7_s-4","guanzi_ch-3_p-7_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"國土疆域之內未被開墾耕種的荒地，在實質上根本不算我們真正的土地；境內人口之中未經教化治理的遊民，在實質上根本不算我們真正的子民！大凡治理撫育萬民的君王，必須依靠平日所積蓄儲備的糧食財富來養育軍民，這不可不深加審察明辨啊！物資積蓄充裕豐厚的國家必定富強，物資積蓄空虛短缺的國家必定貧弱！所以致力於農業生產、充實積蓄糧穀，正是富民強國的根本基石！","analysis":"【題解與地不闢非吾地民不牧非吾民】管仲提出實質國力觀——國土大小不在於地圖虛名，而在於實際開墾耕種的有效面積；人口多寡不在於戶籍數字，而在於受有效治理的生產勞動人口。\\n【詞義訓詁】「地不闢非吾地」：反對虛浮的領土虛榮，強調實質開發；「以所積食之」：以實際儲備保障民生；「務農積穀」：富民之本。\\n【實質國力論】管仲打破了盲目爭奪不毛之地的地緣狂熱，指出唯有轉化為實際糧食產能的土地與受良好訓練組織的人民，才是真正的國家戰略資產。"}},{"id":"guanzi_ch-3_p-8","chapterId":"guanzi_ch-3","order":8,"canonicalText":"人情不二，故民情可得而御也。審其所好惡，則其長短可知也；觀其交遊，則其賢不肖可察也；二者不失，則治民之道得矣。","sentenceIds":["guanzi_ch-3_p-8_s-1","guanzi_ch-3_p-8_s-2","guanzi_ch-3_p-8_s-3","guanzi_ch-3_p-8_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"普天下百姓的本質人情並沒有兩樣（人情不二，皆避苦求樂、趨利避害），所以萬民的情緒心態完全是可以被掌握統御的！仔細審察百姓所喜好的是什麼、所厭惡的是什麼，那麼他們的長處與短處就能一清二楚了；觀察一個人平日所結交的朋友與社交圈子，那麼他是賢能君子還是平庸小人就能明察秋毫了！只要牢牢把握住這兩大根本原則，治理萬民的大道就完全掌握在手中了！","analysis":"【題解與背景】\\n本段選自《管子》〈權修〉第 27 節。屬於古代法家治術代表性經典，記述先賢關於主張法術勢結合、富國強兵、賞罰分明與明法審令之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「人情不二故民情可得而御也審其所好惡則其長短可……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「人」、「情」、「不」、「二」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《管子》知行合一與經世致用之哲理觀念，反映法家先賢關於制度建設、行政效能與嚴明法令之經世智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"guanzi_ch-3_p-9","chapterId":"guanzi_ch-3","order":9,"canonicalText":"地之守在城，城之守在兵，兵之守在人，人之守在粟；故地不闢，則城不固。有身不治，奚待於人？有國不治，奚待於天下？故自修者為天下本。","sentenceIds":["guanzi_ch-3_p-9_s-1","guanzi_ch-3_p-9_s-2","guanzi_ch-3_p-9_s-3","guanzi_ch-3_p-9_s-4","guanzi_ch-3_p-9_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"保衛國土的防線在於堅固城池，守衛城池的關鍵在於精銳軍隊，維持軍隊戰鬥力的根本在於團結人心士氣，而凝聚維持人心的命脈在於充盈的糧食儲備（人之守在粟）！所以荒地若不加開墾生產糧食，城池防守就絕不可能穩固！自身個人品行尚且不能修治健全，又憑什麼指望去要求治理別人呢？自身國家尚且治理不好陷入動亂，又憑什麼指望去君臨統一天下呢？所以統治者加強自身道德與制度修為，是一切平定天下的根本源頭！","analysis":"【題解與地守城城守兵兵守人人守粟】管仲建立環環相扣的國防安全鏈條：地→城→兵→人→粟，並推導出「自修者為天下本」的內聖外王結論！\\n【詞義訓詁】「人之守在粟」：糧食是維繫生命與軍心士氣之終極命脈；「有身不治奚待於人」：反求諸己、修身為本。\\n【國防戰略閉環】防禦的本質不是冰冷的磚石城牆（城），而是人（兵），人的背後是糧食（粟），糧食的背後是農業開發（闢地）。一切宏大戰略最終皆錨定於農業實體經濟。"}},{"id":"guanzi_ch-3_p-10","chapterId":"guanzi_ch-3","order":10,"canonicalText":"商賈在朝，則貨財上流；婦言人事，則賞罰不信；男女無別，則民無廉恥；貨財上流，賞罰不信，民無廉恥，此三者，國之大蠹也。","sentenceIds":["guanzi_ch-3_p-10_s-1","guanzi_ch-3_p-10_s-2","guanzi_ch-3_p-10_s-3","guanzi_ch-3_p-10_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"投機商賈若位列朝廷執掌大權，國家財富金銀就會全部向上層權貴私庫流動兼併（貨財上流）；後宮婦人私下干涉朝政人事任免，國家的各項功賞刑罰就會喪失公信力；男女社交荒淫放蕩毫無界限禮法，全體百姓就會喪失基本的廉潔與羞恥心！財富向權貴壟斷流動、賞罰喪失社會公信、萬民不知榮辱羞恥，這三種嚴重弊端，正是蛀空國家根基的致命毒瘤（國之大蠹）！","analysis":"【題解與國之三蠹商賈在朝婦言人事男女無別】管仲痛斥腐蝕國家肌體的三大致命毒瘤（三蠹）：官商勾結資本壟斷（貨財上流）、裙帶後宮干政（賞罰失信）、道德倫理崩潰（民無廉恥）！\\n【詞義訓詁】「貨財上流」：社會財富被特權階層與投機資本瘋狂兼併吸收；「大蠹」：蠹，音杜，蛀蟲；蛀空國家的致命蛀蟲。\\n【反腐敗與反壟斷警示】管仲極具前瞻性地指出：一旦官商勾結形成特權資本壟斷，社會公平與道德底線將蕩然無存，政權必遭蛀空滅亡。"}},{"id":"guanzi_ch-3_p-11","chapterId":"guanzi_ch-3","order":11,"canonicalText":"一年之計，莫如樹穀；十年之計，莫如樹木；終身之計，莫如樹人。一樹一穫者，穀也；一樹十穫者，木也；一樹百穫者，人也。我 daraus 樹之，天下利之。此治國之大經也。","sentenceIds":["guanzi_ch-3_p-11_s-1","guanzi_ch-3_p-11_s-2","guanzi_ch-3_p-11_s-3","guanzi_ch-3_p-11_s-4","guanzi_ch-3_p-11_s-5","guanzi_ch-3_p-11_s-6","guanzi_ch-3_p-11_s-7","guanzi_ch-3_p-11_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"謀劃一年的短期生計，沒有比種植五穀莊稼更見成效的了；謀劃十年的中期大計，沒有比植樹造林培育林木更獲長遠利益的了；而謀劃一生一世乃至千秋萬代的終身戰略大計，沒有比培養教育優秀人才更為偉大的了！播種一次收穫一次的，是五穀糧食；栽種一次收穫十倍利益的，是樹木森林；培育一次收穫百倍乃至千秋萬代無盡回報的，正是偉大的人才！我們為國家培育出卓越人才，全天下都將因此獲得無盡福祉。這正是治理國家最崇高偉大的根本經典！","analysis":"【題解與一年樹穀十年樹木終身樹人】本段為中華教育哲學與人力資源戰略最輝煌之千古名篇——「十年樹木，百年樹人（終身之計莫如樹人）」的母體出處！\\n【詞義訓詁】「樹」：動詞，種植、培養、投資；「一樹百穫者人也」：人才投資具有百倍乃至無窮的巨大戰略槓桿效應；「天下利之」：造福全人類文明。\\n【教育興邦之最高綱領】管仲將「培育人才（樹人）」置於國家戰略的最頂峯：農業解決當下溫飽（一年），林業解決中期資源（十年），唯有人才教育與科技智慧（終身）才能決定文明千秋萬代的興衰。"}},{"id":"guanzi_ch-3_p-12","chapterId":"guanzi_ch-3","order":12,"canonicalText":"凡牧民者，使士無邪行，女無淫事。士無邪行，教也。女無淫事，訓也。教訓成俗，而刑罰省，數也。刑罰省而民自化，此所謂大治也。","sentenceIds":["guanzi_ch-3_p-12_s-1","guanzi_ch-3_p-12_s-2","guanzi_ch-3_p-12_s-3","guanzi_ch-3_p-12_s-4","guanzi_ch-3_p-12_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"凡是治理百姓的統治者，要讓男子沒有邪惡的行為，讓女子沒有淫亂的事情。男子沒有邪惡的行為，是因為受到了良好的教育；女子沒有淫亂的事情，是因為受到了正確的訓導。教育和訓導一旦形成社會風氣，刑罰自然就會減少，這是有規律可循的。刑罰減少而百姓能夠自我教化，這就是所謂的天下大治。","analysis":"【訓詁與名物】「牧民」即治理百姓，古人以牧羊比喻治民。「士」此處泛指成年男子，「女」指成年女子。「淫事」並非單指男女之慾，也包含一切過度、不合禮教的行為。「省」意為減少。「數也」的「數」指的是必然的規律或道理。\\n【章法與結構】本段論述層層遞進，邏輯嚴密。首先提出治民的目標是讓男女皆無邪行淫事；接著指出達成此目標的方法在於「教」與「訓」；然後說明教訓的效果是形成風俗並減少刑罰；最後導出結論：刑罰省而民自化，即為「大治」。\\n【思想與義理】此段反映了《管子》重視教化、以教化輔助刑罰的治國理念。與純粹依賴嚴刑峻法的法家不同，管仲強調「教訓成俗」，認為只有從根本上改變人民的思想觀念，形成良好的社會風氣，才能真正減少犯罪，達到百姓自我管理的最高政治境界。"}},{"id":"guanzi_ch-3_p-13","chapterId":"guanzi_ch-3","order":13,"canonicalText":"凡牧民者，欲民之有義也；欲民之有義，則小義不可不行；小義不行於國，而求百姓之行大義，不可得也。故治國者，慎於微始。","sentenceIds":["guanzi_ch-3_p-13_s-1","guanzi_ch-3_p-13_s-2","guanzi_ch-3_p-13_s-3","guanzi_ch-3_p-13_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"大凡治理萬民的君王，必定希望全體百姓都具備恪守道義大義的品格；想要讓百姓恪守道義，那麼日常生活中的微小道義（小義）就絕對不可不身體力行推廣！如果日常生活中的守法互助等微小義舉在國家中都無法切實推行，卻妄想在國家危難之際奢求百姓去捨生取義奔赴戰場大義，這是絕對不可能辦到的！所以善於治理國家的君王，必定在最微小的萌芽開端處極其審慎認真！","analysis":"【題解與背景】\\n本段選自《管子》〈權修〉第 32 節。屬於古代法家治術代表性經典，記述先賢關於主張法術勢結合、富國強兵、賞罰分明與明法審令之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「凡牧民者欲民之有義也欲民之有義則小義不可不行……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「凡」、「牧」、「民」、「欲」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《管子》知行合一與經世致用之哲理觀念，反映法家先賢關於制度建設、行政效能與嚴明法令之經世智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"guanzi_ch-4_p-1","chapterId":"guanzi_ch-4","order":1,"canonicalText":"國之所以治亂者三，殺戮刑罰，不足用也。國之所以安危者四，城郭險阻，不足守也。國之所以富貧者五，山林澤梁，不足恃也。故治國在於明本。","sentenceIds":["guanzi_ch-4_p-1_s-1","guanzi_ch-4_p-1_s-2","guanzi_ch-4_p-1_s-3","guanzi_ch-4_p-1_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"決定國家走向大治或大亂的根本因素有三條（三本），單純依靠殘酷的殺戮刑罰是遠遠不足以治理好國家的；決定國家走向安全或危殆的根本因素有四條（四固），單純依靠險峻的城郭高牆是遠遠不足以防守得住的；決定國家走向富裕或貧困的根本因素有五條（五事），單純依仗富饒的名山大川湖泊山林也是不足以長期依賴的！所以治理國家的至高要務，在於徹底明辨掌握這些根本源頭！","analysis":"【題解與背景】\\n本段選自《管子》〈立政〉第 33 節。屬於古代法家治術代表性經典，記述先賢關於主張法術勢結合、富國強兵、賞罰分明與明法審令之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「國之所以治亂者三殺戮刑罰不足用也國之所以安危……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「國」、「所」、「治」、「亂」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《管子》知行合一與經世致用之哲理觀念，反映法家先賢關於制度建設、行政效能與嚴明法令之經世智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"guanzi_ch-4_p-2","chapterId":"guanzi_ch-4","order":2,"canonicalText":"君之所審者三：一曰德不當其位；二曰功不當其祿；三曰能不當其官；此三本者，治亂之原也。故德薄而位尊，功微而祿厚，無能而官大，此國之所以亂也。故明君審其德，考其功，量其能，然後授之。","sentenceIds":["guanzi_ch-4_p-2_s-1","guanzi_ch-4_p-2_s-2","guanzi_ch-4_p-2_s-3","guanzi_ch-4_p-2_s-4","guanzi_ch-4_p-2_s-5","guanzi_ch-4_p-2_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"君王所必須嚴格審查的根本事項有三條（三本）：第一，品德修養與其身居的尊貴職位是否相稱（德不當其位）；第二，實際戰功貢獻與其享受的厚重俸祿是否相稱（功不當其祿）；第三，真實業務能力與其管轄的官職職權是否相稱（能不當其官）！這三條根本原則，是決定國家大治與大亂的最根本源頭！所以德行淺薄卻身居至尊高位，功勞微小卻享受萬鍾厚祿，毫無才幹卻掌管核心大官，這正是國家之所以陷入萬劫不復大亂的根本原因啊！所以英明的君主必定嚴格審查其德行，考核其真實功績，計量其專業能力，然後才鄭重授予相應官位爵祿！","analysis":"【題解與三本治亂之源德當位功當祿能當官】本段為中國古代公務員制度與官吏選拔考績之最經典憲章——德當其位、功當其祿、能當其官！\\n【詞義訓詁】「當」：音蕩，相稱、匹配；「三本」：選官任官的三大根本底線；「德薄位尊、功微祿厚、無能官大」：官場腐敗與體制潰爛的三大典型徵兆。\\n【現代人力資源配置鐵律】任何組織的崩潰都始於德不配位、功不配祿、能不配官。唯有建立德、功、能精確匹配的激勵考核體系，政權才能長治久安。"}},{"id":"guanzi_ch-4_p-3","chapterId":"guanzi_ch-4","order":3,"canonicalText":"右三本。審德、考功、量能，治國之大綱也。","sentenceIds":["guanzi_ch-4_p-3_s-1","guanzi_ch-4_p-3_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"以上為《三本》篇要義。審度德行、考核功績、衡量才幹，這正是治理國家的至高大綱！","analysis":"【題解與背景】\\n本段選自《管子》〈立政〉第 35 節。屬於古代法家治術代表性經典，記述先賢關於主張法術勢結合、富國強兵、賞罰分明與明法審令之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「右三本審德考功量能治國之大綱也……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「右」、「三」、「本」、「審」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《管子》知行合一與經世致用之哲理觀念，反映法家先賢關於制度建設、行政效能與嚴明法令之經世智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"guanzi_ch-4_p-4","chapterId":"guanzi_ch-4","order":4,"canonicalText":"君之所慎者四：一曰大德不至仁，不可以授國柄。二曰見賢不能讓，不可與尊位。三曰罰避親貴，不可使主刑。四曰好戰貪利，不可使掌兵。此四固者，安危之機也。","sentenceIds":["guanzi_ch-4_p-4_s-1","guanzi_ch-4_p-4_s-2","guanzi_ch-4_p-4_s-3","guanzi_ch-4_p-4_s-4","guanzi_ch-4_p-4_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"君王所必須極度審慎警惕的防範事項有四條（四固）：\\n第一，道德名望縱然看似宏大但內心缺乏至誠仁愛之心的人，絕對不可以把執掌國家政權的最高權柄授予他；\\n第二，看見天下真正賢能之人卻嫉妒不肯主動讓賢舉賢的人，絕對不可以給予他崇高尊貴的宰相位階；\\n第三，執法行刑時畏懼權貴、偏袒庇護王親國戚的人，絕對不可以任命他主管國家司法與刑獄大權；\\n第四，窮兵黷武生性好戰、貪圖眼前戰利私利的人，絕對不可以任命他執掌國家三軍兵權！這四條固守國家的底線原則，正是決定政權生死存亡安危的最關鍵樞紐！","analysis":"【題解與四固安危之機與最高用人禁忌】管仲確立最高領導層任命的四大絕對禁忌：不仁者不可授國柄、嫉賢者不可居尊位、徇私者不可主刑法、好戰者不可掌兵權！\\n【詞義訓詁】「四固」：鞏固國家安全防線的四大任命禁令；「國柄」：國家最高執政權；「罰避親貴」：司法不公、不敢向特權階層開刀；「好戰貪利」：軍事冒險主義狂人。\\n【政治安全紅線】這四條紅線精準鎖定了歷史上導致帝國覆亡的四類致命奸邪，為最高決策層提供了極其嚴格的政治防禦機制。"}},{"id":"guanzi_ch-4_p-5","chapterId":"guanzi_ch-4","order":5,"canonicalText":"右四固。慎選輔弼，安邦固本；防微杜漸，社稷長存。","sentenceIds":["guanzi_ch-4_p-5_s-1","guanzi_ch-4_p-5_s-2","guanzi_ch-4_p-5_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"以上所論述的是四固的原則。只有謹慎地選擇輔佐君王的賢臣，才能安定國家、鞏固政權的根本；在禍患剛有徵兆時就加以防範並杜絕其發展，國家的政權才能夠長久地存續下去。","analysis":"【訓詁與名物】：「右」指上文，古人書寫由右至左，故稱上文為右。「四固」是《管子》中鞏固政權的四個基本條件。「輔弼」指輔助君主治理國家的大臣。「防微杜漸」指在錯誤或壞事剛剛露出苗頭時就加以制止，不讓其發展壯大。「社稷」原指土神與穀神，後代指國家政權。\\n\\n【章法與結構】：這段文字是對前文「四固」論述的高度概括與總結。全段由兩個對仗工整的四字句與六字句組合而成：「慎選輔弼」對應「防微杜漸」，「安邦固本」對應「社稷長存」。語言簡練，節奏明快，具有極強的格言性質，便於記憶與傳誦。\\n\\n【思想與義理】：此段集中體現了法家與政治家對於政權建設的深刻洞見。其核心思想有二：一是「用人」，即選拔賢能的輔弼大臣是國家長治久安的前提；二是「防患」，即治國必須有前瞻性，不能等危機爆發纔去應對，而應在微小的徵兆中發現問題並及時掐滅。這種防患於未然的危機意識，對於任何時代的國家治理都具有重要的借鑒意義。"}},{"id":"guanzi_ch-4_p-6","chapterId":"guanzi_ch-4","order":6,"canonicalText":"君之所務者五：一曰山澤不救於火，草木不植成，國之貧也。二曰溝瀆不遂於隘，鄣水不安其藏，國之貧也。三曰桑麻不植於野，六畜不蕃於家，國之貧也。四曰田疇不闢於荒，五穀不殖於地，國之貧也。五曰工匠不造其器，商賈不通其貨，國之貧也。此五事者，富貧之原也。","sentenceIds":["guanzi_ch-4_p-6_s-1","guanzi_ch-4_p-6_s-2","guanzi_ch-4_p-6_s-3","guanzi_ch-4_p-6_s-4","guanzi_ch-4_p-6_s-5","guanzi_ch-4_p-6_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"君王所必須親自抓落實的五大經濟生產實務（五事）：\\n第一，名山大澤發生森林山火若不及時撲救，草木林木無法種植成林，這是導致國家貧困的第一根源；\\n第二，溝渠河道在狹隘險要處淤塞無法疏通，堤壩防洪蓄水不能安穩儲存，這是導致水旱成災國家貧困的第二根源；\\n第三，桑樹麻草不全面種植在田野之中，馬牛羊豬狗雞六畜不在農家繁衍興旺，這是導致布帛肉食短缺國家貧困的第三根源；\\n第四，田疇農田不從荒地中大力開墾，五穀雜糧不在大地中廣泛增產繁衍，這是導致糧食匱乏國家貧困的第四根源；\\n第五，手工匠人不製造精良實用的工具器械，客商商人不流通天下各地的物資貨物，這是導致流通阻滯國家貧困的第五根源！這五項實體經濟要務，正是決定國家走向繁榮富強或走向赤貧衰竭的根本源頭！","analysis":"【題解與五事實體經濟富貧之源】本段為中國古代最早之全產業鏈實體經濟發展規劃——管仲系統提出林業生態、水利工程、桑麻畜牧、農耕種植與工商業流通五大支柱產業！\\n【詞義訓詁】「五事」：林業、水利、畜牧、農耕、工商五大經濟基本盤；「鄣水」：鄣通障，防洪堤壩蓄水；「商賈不通其貨」：商品物資流通阻滯。\\n【古代全產業鏈經濟規劃】管仲將生態環境保護（山火林木）、基礎設施建設（溝瀆水利）與農工商業緊密結合，構建了古代最完備的國民經濟發展體系。"}},{"id":"guanzi_ch-4_p-7","chapterId":"guanzi_ch-4","order":7,"canonicalText":"右五事。興修水利，務本農桑；工商業通，富國之源。","sentenceIds":["guanzi_ch-4_p-7_s-1","guanzi_ch-4_p-7_s-2","guanzi_ch-4_p-7_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"以上所論述的是國家管理的五事。大力興建和修治水利工程，致力於發展作為國家根本的農業與桑蠶業；同時也要讓手工業和商業保持流通與繁榮，這些都是使國家富強的根本源泉。","analysis":"【訓詁與名物】：「右」即上文。「五事」指《管子》中提出的國家應當抓好的五項重要經濟與行政事務。「水利」指防洪灌溉等水利工程。「務本」指致力於根本，古代以農為本。「農桑」指農業與蠶桑業，代指農業生產。「工商業通」指手工業與商業貿易暢通無阻。「源」指源泉。\\n\\n【章法與結構】：本段文字作為總結性的結語，句式極其精簡，採用了四字一句的駢文化結構。「興修水利」與「務本農桑」並列，強調了農業基礎的建設；隨後以「工商業通」作為補充與昇華，最後一句「富國之源」則是對前面所有行為的目的與結果進行了總結定性。條理清晰，重點突出。\\n\\n【思想與義理】：這短短十六個字，高度濃縮了《管子》一書中卓越的經濟思想。不同於後世許多重農抑商的思想，《管子》展現出了更為宏大與全面的經濟視野。他不僅強調了「農桑」與「水利」作為國家生存之本的基礎性地位，同時也極具前瞻性地指出了「工商業通」的重要性。農工商並重，貨暢其流，這才是國家積累財富、走向富強的真正源泉，體現了先秦時期齊國獨特的重商與務實精神。"}},{"id":"guanzi_ch-4_p-8","chapterId":"guanzi_ch-4","order":8,"canonicalText":"分國以為五鄉，鄉為之師，分鄉以為五州，州為之長。分州以為十里，裏為之尉。分裏以為十遊，遊為之宗。分遊以為十家，家為之長。層層統攝，上下相維，則天下之民莫敢不順令矣。","sentenceIds":["guanzi_ch-4_p-8_s-1","guanzi_ch-4_p-8_s-2","guanzi_ch-4_p-8_s-3","guanzi_ch-4_p-8_s-4","guanzi_ch-4_p-8_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"劃分全國行政區域為五大鄉，每個鄉設立一名鄉師主管；劃分每個鄉為五個州，每個州設立一名州長主管；劃分每個州為十個裏，每個裏設立一名裏尉主管；劃分每個裏為十個遊，每個遊設立一名遊宗主管；劃分每個遊為十個家庭，每家設立一名家長負責！層層建立嚴密的組織架構統轄管理，上下級之間如網維般緊密相連互相監督，那麼普天下的百姓就沒有一人敢於違抗遵從政令了！","analysis":"【題解與背景】\\n本段選自《管子》〈立政〉第 40 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「分國以為五鄉鄉為之師分鄉以為五州州為之長……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「分」、「國」、「以」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《管子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：guanzi_ch-4_p-8）。"}},{"id":"guanzi_ch-4_p-9","chapterId":"guanzi_ch-4","order":9,"canonicalText":"孟春之朝，君自聽朝，論爵賞校官，終五日。季冬之夕，君自聽朝，論罰罪刑殺，亦終五日。正月之朔，百官受令於朝，修法以待政。此首憲之法也。","sentenceIds":["guanzi_ch-4_p-9_s-1","guanzi_ch-4_p-9_s-2","guanzi_ch-4_p-9_s-3","guanzi_ch-4_p-9_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"在初春的正月早晨，國君應當親自臨朝聽政，評定爵位賞賜並考核各級官員，這個過程要持續整整五天。在深冬十二月的傍晚，國君也要親自臨朝聽政，審理判決犯罪者的刑罰乃至死刑，這同樣要持續整整五天。在新年的第一天，百官要在朝廷上接受國君的政令，研習與整頓國家的法律，以便等待並執行接下來的政務。這就是被稱為首憲（即頒布國家最高法令）的法則。","analysis":"【訓詁與名物】：「孟春」指春季的第一個月，即農曆正月。「朝」指早晨，也指朝廷。「季冬」指冬季的最後一個月，即農曆十二月。「夕」指傍晚或月末。「朔」指每月的初一，此處指正月初一。「校官」指考核官員的政績。「受令」指接受政令。「修法」指修明、學習法令。「首憲」指首要的法令，或歲首頒布的國家根本大綱。\\n\\n【章法與結構】：本段在時間與事件的安排上呈現出高度的對稱性與儀式感。「孟春之朝」與「季冬之夕」相對，「論爵賞校官」與「論罰罪刑殺」相對，兩次政務活動皆強調了「君自聽朝」與「終五日」。最後以「正月之朔」百官受令為總結，點明這是貫穿全年的「首憲之法」。敘述有條不紊，法度森嚴。\\n\\n【思想與義理】：這段文字深刻體現了法家重法度、重賞罰以及順應天時的政治理念。春季萬物生長，故在此時「論爵賞」，順應了天道生發之氣；冬季萬物閉藏，故在此時「論刑殺」，順應了天道肅殺之威。這種「春夏賞，秋冬刑」的設計，將人間的政治律令與自然界的宇宙秩序緊密結合，賦予了王權與法律神聖不可侵犯的色彩。同時，強調國君親自主持並明確時間，彰顯了賞罰權柄不可下移的君主集權思想。"}},{"id":"guanzi_ch-4_p-10","chapterId":"guanzi_ch-4","order":10,"canonicalText":"右首憲。孟春行賞，季冬決刑；歲首布憲，綱紀嚴明。","sentenceIds":["guanzi_ch-4_p-10_s-1","guanzi_ch-4_p-10_s-2","guanzi_ch-4_p-10_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"以上所論述的是關於首憲的制度。在初春的正月執行賞賜，在深冬的十二月判決刑罰；在每一年的開頭頒布國家的根本法令，這樣就能使國家的法度與綱紀保持嚴肅而明朗。","analysis":"【訓詁與名物】：「右」指上文。「首憲」指歲首頒布的國家根本大綱與法令。「孟春」即正月。「季冬」即十二月。「布憲」指頒布法律與政令。「綱紀」指國家的法度與秩序。「嚴明」指嚴肅、嚴格且清晰明瞭。\\n\\n【章法與結構】：此段為前文的總結句，採用了四字一句的駢偶句式，言簡意賅。「孟春行賞」與「季冬決刑」構成工整的對仗，濃縮了前文中關於時間與賞罰的詳細規定；「歲首布憲」點出了政務開展的核心環節；「綱紀嚴明」則是對貫徹這套制度後所達到的政治效果的終極概括。\\n\\n【思想與義理】：短短十六字，提綱挈領地總結了《管子》中關於依法治國與順天應時的核心政治主張。它強調了治理國家必須有章可循、有法可依（歲首布憲），並且賞罰的執行必須分明且符合自然時令的規律（春賞冬刑）。這反映了中國古代政治哲學中將「天道」與「人事」相合一的深邃思想，旨在通過嚴明的法度來構建一個秩序井然、賞罰有信的理想社會結構。"}},{"id":"guanzi_ch-4_p-11","chapterId":"guanzi_ch-4","order":11,"canonicalText":"凡將舉事，令必先出，曰事將為。其賞罰之數，必先明之，立事者，謹守令以行賞罰，計事致令，復賞罰之數，然後發之。此首事之法也。","sentenceIds":["guanzi_ch-4_p-11_s-1","guanzi_ch-4_p-11_s-2","guanzi_ch-4_p-11_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"大凡國家將要興辦重大工程、發動重大政務或軍事行動（凡將舉事），各項政策號令必須提前向天下公布，明確告知即將舉辦何項事業；相應的戰功賞賜與違法懲罰的具體標準數額，必須預先向全體軍民公布昭明！負責主管落實該事業的官員，必須嚴格恪守法令依據來執行賞罰，核算具體工作成果、驗證是否達到法令標準，複查賞罰的具體數額無誤，然後才正式發放賞賜推行！這就是開展重大政務的根本程序法度（首事之法）！","analysis":"【題解與首事程序法與令必先出預先告知】管仲創立中國古代最早的「行政程序法與預先告知原則（令必先出、賞罰先明）」！\\n【詞義訓詁】「令必先出」：法律與政策不溯及既往、政令走在行動之前；「賞罰之數必先明之」：量化公布獎懲標準；「首事之法」：重大行政舉措標準化工作流程。\\n【程序正義與法治精神】公權力在採取行動前必須提前公開透明告示規則，杜絕突襲式執法與暗箱操作，體現了高度進步的法治程序文明。"}},{"id":"guanzi_ch-4_p-12","chapterId":"guanzi_ch-4","order":12,"canonicalText":"右首事。舉事先令，賞罰預明；計功覈實，程序嚴整。","sentenceIds":["guanzi_ch-4_p-12_s-1","guanzi_ch-4_p-12_s-2","guanzi_ch-4_p-12_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"以上所論述的是關於首事（即開展重要事務）的原則。在興辦任何重要事務之前，都必須先發布明確的政令，並將相關的賞罰標準預先向大眾宣告明白；在事後評定功勞時，必須根據實際的成效進行嚴格的核查，整個行事的程序必須保持嚴密與整齊。","analysis":"【訓詁與名物】：「右」指上文。「首事」指興辦國家重大事務的原則與首要步驟。「舉事」指發起、辦理事情。「先令」指預先發布指令與要求。「預明」指事先闡明、公開。「計功」指計算、評定功勞。「覈實」（hé shí）指審覈查實。「程序」指辦事的步驟與順序。「嚴整」指嚴格而有條理。\\n\\n【章法與結構】：本段依舊延續了總結性文字四字一句的精煉風格，句式對仗齊整。「舉事先令」對應行動的開端，「賞罰預明」對應規則的建立；「計功覈實」是事後的檢驗，「程序嚴整」則是對整體工作流程的總體要求。從事前、事中到事後，邏輯鏈條完整，一氣呵成。\\n\\n【思想與義理】：這段話展現了古代極為先進的行政管理與績效考核思想。它強調了政府在執行政策時必須具備極高的透明度與程序正義。事先公佈政令與賞罰標準（不教而誅謂之虐），能夠最大限度地統一思想、激發民力；事後依據客觀事實進行嚴格的績效覈查（計功覈實），則杜絕了弄虛作假與賞罰不明的弊端。這種重視法治程序與客觀實效的管理理念，不僅是法家治國的精髓，在現代行政管理學中同樣閃爍著智慧的光芒。"}},{"id":"guanzi_ch-4_p-13","chapterId":"guanzi_ch-4","order":13,"canonicalText":"修火憲，敬山澤，林藪積草，夫財之所出，以時禁發焉。使民足於宮室之用，薪蒸之所積，虞師之事也。省官減冗，各司其職，則國事修矣。","sentenceIds":["guanzi_ch-4_p-13_s-1","guanzi_ch-4_p-13_s-2","guanzi_ch-4_p-13_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"整飭頒布嚴禁野外用火的防火法令（修火憲），恭敬保護名山大川湖泊水澤（敬山澤）；山林草澤所蓄積的各類豐富木材草料，正是國家自然財富生產的源泉，必須嚴格順應自然生態時令實施封山禁伐與適時開放採伐（以時禁發）！使百姓在建造居室宮殿時木材原料充足完備，柴火薪柴儲備充裕無缺，這正是虞衡山林水澤官員（虞師）的專屬本職職責！精簡多餘冗官、裁減冗員機構，使百官各司其職，那麼國家各項大政自然修明治理了！","analysis":"【題解與修火憲敬山澤虞師職守與生態保護】管仲詳述古代生態環境法（火憲、山澤保護、以時禁發）與林業官員（虞師）專責，並提出「省官減冗」之精兵簡政理念。\\n【詞義訓詁】「修火憲」：防火法令；「林藪」：湖澤沼澤生長之草木；「以時禁發」：按生態季節封山育林與開放採伐；「虞師」：掌管山林川澤生態資源之古代官職；「省官減冗」：精簡機構冗員。\\n【古代生態可持續發展法】管仲嚴格規定：不到草木凋零不許進山砍柴，不到魚鱉繁育結束不許下網捕魚，保護自然生態自我修復能力，極具現代生態文明意識。"}},{"id":"guanzi_ch-4_p-14","chapterId":"guanzi_ch-4","order":14,"canonicalText":"右省官。保護生態，時禁時發；精簡機構，政令暢通。","sentenceIds":["guanzi_ch-4_p-14_s-1","guanzi_ch-4_p-14_s-2","guanzi_ch-4_p-14_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"以上為《省官》篇要義。依法保護自然生態資源，按照時令嚴格封禁與適時開放；精簡政府機構裁減冗員，保證國家政令高效暢通！","analysis":"【題解與背景】\\n本段選自《管子》〈立政〉第 46 節。屬於古代法家治術代表性經典，記述先賢關於主張法術勢結合、富國強兵、賞罰分明與明法審令之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「右省官保護生態時禁時發精簡機構政令暢通……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「右」、「省」、「官」、「保」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《管子》知行合一與經世致用之哲理觀念，反映法家先賢關於制度建設、行政效能與嚴明法令之經世智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"guanzi_ch-4_p-15","chapterId":"guanzi_ch-4","order":15,"canonicalText":"度爵而制服，量祿而用財，飲食有量，衣服有制，宮室有度，六畜人徒有數，舟車陳器有禁，修生則有賞，奢靡則有刑。此服制之大法也。","sentenceIds":["guanzi_ch-4_p-15_s-1","guanzi_ch-4_p-15_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"根據官爵品階的高低來制定等級禮服（度爵制服），根據俸祿收入的多少來合理規劃開支財用（量祿用財）！日常飲食有節制規格，穿戴衣服有嚴格禮制，宮殿居室有法度規格，飼養六畜與役使僕從有法定限額，舟船車駕與陳列器具有禁令限制！勤儉持家、發展生產有功者給予國家表彰賞賜，驕奢淫逸、逾矩僭越奢靡者處以嚴厲法律刑罰！這就是國家規範社會等級與遏制奢侈的根本大法（服制大法）！","analysis":"【題解與度爵制服量祿用財與反奢侈服制法】管仲制定嚴格的消費禮制與反奢靡法規——將衣食住行、車馬僕役嚴格限制在與其爵祿相匹配的法度之內，修生者賞、奢靡者刑！\\n【詞義訓詁】「度爵而制服」：禮服等級與爵位相稱；「量祿而用財」：量入為出；「修生」：勤儉治生發展生產；「服制」：古代消費與禮製法規。\\n【遏制消費主義與等級秩序】在物質匱乏的先秦時代，防止貴族階層惡性攀比、揮霍浪費，是維護社會資本積累與階層和諧的關鍵法制手段。"}},{"id":"guanzi_ch-4_p-16","chapterId":"guanzi_ch-4","order":16,"canonicalText":"右服制。量入為出，節儉尚質；明定法度，禁絕奢靡。","sentenceIds":["guanzi_ch-4_p-16_s-1","guanzi_ch-4_p-16_s-2","guanzi_ch-4_p-16_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"以上為《服制》篇要義。各級階層量入為出規劃開支，崇尚節儉質樸淳厚風氣；向天下明確制定生活法度，堅決禁絕浮華奢靡之風！","analysis":"【題解與背景】\\n本段選自《管子》〈立政〉第 48 節。屬於古代法家治術代表性經典，記述先賢關於主張法術勢結合、富國強兵、賞罰分明與明法審令之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「右服制量入為出節儉尚質明定法度禁絕奢靡……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「右」、「服」、「制」、「量」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《管子》知行合一與經世致用之哲理觀念，反映法家先賢關於制度建設、行政效能與嚴明法令之經世智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"guanzi_ch-4_p-17","chapterId":"guanzi_ch-4","order":17,"canonicalText":"寢兵之說勝，則險阻不守；兼愛之說勝，則士卒不戰。全生之說勝，則廉恥不立。私議自貴之說勝，則法令不行。此九敗之原也，明君審禁之。","sentenceIds":["guanzi_ch-4_p-17_s-1","guanzi_ch-4_p-17_s-2","guanzi_ch-4_p-17_s-3","guanzi_ch-4_p-17_s-4","guanzi_ch-4_p-17_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"廢棄軍隊武備的極端非戰消極之說（寢兵之說）若在社會上佔了上風，那麼邊疆的險要要塞就再也無人願意堅守；墨家無原則的兼愛之說若在軍中佔了上風，那麼面臨強敵入侵時士卒就不會奮勇出戰；道家全生保命、自私苟全之說若在社會上佔了上風，那麼崇高的道德廉恥就再也無法樹立；士人各抒私己之見、自命清高自貴的言論若在朝野佔了上風，那麼國家統一的法律政令就再也無法順利推行！這些都是導致國家走向崩潰滅亡的九敗之源頭，英明的君主必定嚴格審查並依法予以禁止！","analysis":"【題解與批判九敗邪說維護國家意識形態】管仲批判「寢兵、兼愛、全生、私議自貴」等瓦解國防意志與法律權威的極端思潮，確立國家安全與法治的核心意識形態。\\n【詞義訓詁】「寢兵之說」：極端和平主義導致國防廢弛；「全生之說」：極端利己主義導致無人為國獻身；「私議自貴」：以個人私見對抗國家法令；「九敗」：瓦解國家的九種意識形態敗局。\\n【國家意識形態安全】強大的國防與法治需要全民族共同的意志認同。若放任消解國家認同與戰鬥意志的虛無思潮氾濫，國家終將在強鄰入侵時不堪一擊。"}},{"id":"guanzi_ch-4_p-18","chapterId":"guanzi_ch-4","order":18,"canonicalText":"右九敗。辨明邪正，固守法度；嚴防偏說，國家永固。","sentenceIds":["guanzi_ch-4_p-18_s-1","guanzi_ch-4_p-18_s-2","guanzi_ch-4_p-18_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"以上為《九敗》篇要義。明辨思想的邪正是非，堅決固守國家的法度綱紀；嚴密防範偏激有害思潮瓦解人心，保證國家政權永固安寧！","analysis":"【題解與九敗要義總結】本段總括思想意識形態引導與法度防線的核心地位，堅決防範極端思潮瓦解國防與法治。\\n【詞義訓詁】「辨明邪正」：明辨各種政治思想學說的是非利弊；「固守法度」：堅定維護國家憲製法規的權威；「國家永固」：以清明的意識形態保障政權長治久安。\\n【意識形態安全】國防與法治的基石在於全民共識。及時辨識並糾正消解國家戰鬥力與法制權威的極端理論，是確保國家安全的根本。"}},{"id":"guanzi_ch-4_p-19","chapterId":"guanzi_ch-4","order":19,"canonicalText":"期而致，使而往，百姓捨己以上為心者，教之所期也。始於不足見，終於不可及，一人服之，萬人從之，此七觀之大法也。","sentenceIds":["guanzi_ch-4_p-19_s-1","guanzi_ch-4_p-19_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"約定時間就能迅速準時集結，派遣差遣就能奮勇勇往直前，全體百姓能夠自覺放下個人私利而以國家君上大局為核心意志（捨己以上為心），這正是國家推行道德教化所期望達到的崇高境界！這項偉大的教化工程在最初萌芽之時看似微不足道難以察覺（始於不足見），然而日積月累最終卻能達到世人難以企及的神妙巔峯（終於不可及）！一人由衷折服踐行，天下萬民便紛紛景從跟隨！這正是考察國家治理成效的七觀根本大法！","analysis":"【題解與教化之所期與七觀大法】本段論述道德教化由微至著、一人引領萬人景從的巨大精神力量，確立「七觀」考察國家治理的終極標準。\\n【詞義訓詁】「期而致，使而往」：軍民行動高度自律高效；「捨己以上為心」：化私為公、具有強烈的集體榮譽感；「始於不足見，終於不可及」：積累教化由量變到質變之神奇規律。\\n【社會動員的最高境界】當一個國家的百姓自覺將個人命運與國家前途融為一體時，所爆發出的組織力與創造力將是無可限量的。"}},{"id":"guanzi_ch-4_p-20","chapterId":"guanzi_ch-4","order":20,"canonicalText":"右七觀。化民成俗，一人唱而萬人和；德法兼施，天下大治。此立政之終始也。","sentenceIds":["guanzi_ch-4_p-20_s-1","guanzi_ch-4_p-20_s-2","guanzi_ch-4_p-20_s-3","guanzi_ch-4_p-20_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"},{"label":"維基文庫《管子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E7%AE%A1%E5%AD%90"}],"readingAid":{"translation":"以上是關於七種觀察和治理國家的方法總結。教化百姓並形成良好的風俗，只要在上位者一人倡導，就會有成千上萬的百姓響應跟隨；道德教化與法律刑罰同時並用，天下就能達到大治的境界。這就是建立政權、治理國家的始終根本所在。","analysis":"【訓詁與名物】「右七觀」的「右」在古文中常代指「上文」或「前述」，因為古人書寫由右至左。「唱」同「倡」，倡導、發起。「和」是附和、響應。「終始」在此處指根本、始終如一的原則或總綱。\\n【章法與結構】作為總結性的段落，此段文字簡潔有力。先以「右七觀」作結，承接上文；接著用「一人唱而萬人和」形容教化的強大感染力；再以「德法兼施，天下大治」點出治國的核心策略；最後以「此立政之終始也」作為全篇的宏大結語。\\n【思想與義理】這段話總結了齊國管仲學派的治國精髓，即「德法兼施」。它既肯定了儒家所強調的道德教化（化民成俗）和君主以身作則的影響力，同時也包容了法家對法律制度的重視。這種兼容並蓄的思想，正是齊國能夠稱霸春秋的重要理論基礎。"}}],"sentences":[{"id":"guanzi_ch-2_p-9_s-1","passageId":"guanzi_ch-2_p-9","order":1,"canonicalText":"日月不明，天不易也；","chunks":[["日月不明，天不易也；","zh-Hant"]]},{"id":"guanzi_ch-2_p-9_s-2","passageId":"guanzi_ch-2_p-9","order":2,"canonicalText":"山高而不見，地不易也。","chunks":[["山高而不見，地不易也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-9_s-3","passageId":"guanzi_ch-2_p-9","order":3,"canonicalText":"言而不可復者，君不言也；","chunks":[["言而不可復者，君不言也；","zh-Hant"]]},{"id":"guanzi_ch-2_p-9_s-4","passageId":"guanzi_ch-2_p-9","order":4,"canonicalText":"行而不可再者，君不行也。","chunks":[["行而不可再者，君不行也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-9_s-5","passageId":"guanzi_ch-2_p-9","order":5,"canonicalText":"凡言必信，凡行必果，此明君之大節也。","chunks":[["凡言而不可復，行而不可再者，有國者之大禁也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-2_s-1","passageId":"guanzi_ch-3_p-2","order":1,"canonicalText":"地博而國貧者，野不闢也，民眾而兵弱者，民無取也。","chunks":[["地博而國貧者，野不闢也，民眾而兵弱者，民無取也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-2_s-2","passageId":"guanzi_ch-3_p-2","order":2,"canonicalText":"故末產不禁，則野不闢。","chunks":[["故末產不禁，則野不闢。","zh-Hant"]]},{"id":"guanzi_ch-3_p-2_s-3","passageId":"guanzi_ch-3_p-2","order":3,"canonicalText":"賞罰不信，則民無取。","chunks":[["賞罰不信，則民無取。","zh-Hant"]]},{"id":"guanzi_ch-3_p-2_s-4","passageId":"guanzi_ch-3_p-2","order":4,"canonicalText":"故務本禁末，信賞必罰，富國強兵之道也。","chunks":[["野不闢，民無取，外不可以應敵，內不可以固守，故曰有萬乘之號，而無千乘之用，而求權之無輕，不可得也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-8_s-1","passageId":"guanzi_ch-3_p-8","order":1,"canonicalText":"人情不二，故民情可得而御也。","chunks":[["人情不二，故民情可得而御也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-8_s-2","passageId":"guanzi_ch-3_p-8","order":2,"canonicalText":"審其所好惡，則其長短可知也；","chunks":[["審其所好惡，則其長短可知也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-8_s-3","passageId":"guanzi_ch-3_p-8","order":3,"canonicalText":"觀其交遊，則其賢不肖可察也；","chunks":[["觀其交遊，則其賢不肖可察也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-8_s-4","passageId":"guanzi_ch-3_p-8","order":4,"canonicalText":"二者不失，則治民之道得矣。","chunks":[["二者不失，則民能可得而官也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-1_s-1","passageId":"guanzi_ch-4_p-1","order":1,"canonicalText":"國之所以治亂者三，殺戮刑罰，不足用也。","chunks":[["國之所以治亂者三，殺戮刑罰，不足用也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-1_s-2","passageId":"guanzi_ch-4_p-1","order":2,"canonicalText":"國之所以安危者四，城郭險阻，不足守也。","chunks":[["國之所以安危者四，城郭險阻，不足守也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-1_s-3","passageId":"guanzi_ch-4_p-1","order":3,"canonicalText":"國之所以富貧者五，山林澤梁，不足恃也。","chunks":[["國之所以富貧者五，輕稅租，薄賦斂，不足恃也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-1_s-4","passageId":"guanzi_ch-4_p-1","order":4,"canonicalText":"故治國在於明本。","chunks":[["治國有三本，而安國有四固，而富國有五事，五事五經也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-11_s-1","passageId":"guanzi_ch-4_p-11","order":1,"canonicalText":"凡將舉事，令必先出，曰事將為。","chunks":[["凡將舉事，令必先出，曰事將為。","zh-Hant"]]},{"id":"guanzi_ch-4_p-11_s-2","passageId":"guanzi_ch-4_p-11","order":2,"canonicalText":"其賞罰之數，必先明之，立事者，謹守令以行賞罰，計事致令，復賞罰之數，然後發之。","chunks":[["其賞罰之數，必先明之，立事者，謹守令以行賞罰，計事致令，復賞罰之所加，有不合於令之所謂者，雖有功利，則謂之專制，罪死不赦。","zh-Hant"]]},{"id":"guanzi_ch-4_p-11_s-3","passageId":"guanzi_ch-4_p-11","order":3,"canonicalText":"此首事之法也。","chunks":[["首事既布，然後可以舉事。","zh-Hant"]]},{"id":"guanzi_ch-1_p-1_s-1","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-1","order":1,"canonicalText":"凡有地牧民者，務在四時，守在倉廩。","chunks":[]},{"id":"guanzi_ch-1_p-1_s-2","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-1","order":2,"canonicalText":"國多財，則遠者來，地闢舉，則民留處；","chunks":[]},{"id":"guanzi_ch-1_p-1_s-3","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-1","order":3,"canonicalText":"倉廩實，則知禮節；","chunks":[]},{"id":"guanzi_ch-1_p-1_s-4","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-1","order":4,"canonicalText":"衣食足，則知榮辱。","chunks":[]},{"id":"guanzi_ch-1_p-1_s-5","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-1","order":5,"canonicalText":"上服度，則六親固。","chunks":[]},{"id":"guanzi_ch-1_p-1_s-6","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-1","order":6,"canonicalText":"四維張，則君令行。","chunks":[]},{"id":"guanzi_ch-1_p-1_s-7","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-1","order":7,"canonicalText":"故省刑之要，在禁微而審度。","chunks":[]},{"id":"guanzi_ch-1_p-2_s-1","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-2","order":1,"canonicalText":"右國頌。","chunks":[]},{"id":"guanzi_ch-1_p-2_s-2","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-2","order":2,"canonicalText":"故治國之要，務在積穀富民，四維既張，天下歸心。","chunks":[]},{"id":"guanzi_ch-1_p-3_s-1","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-3","order":1,"canonicalText":"國有四維，一維絕則傾，二維絕則危，三維絕則覆，四維絕則滅。","chunks":[]},{"id":"guanzi_ch-1_p-3_s-2","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-3","order":2,"canonicalText":"傾可正也，危可安也，覆可起也，滅不可復錯也。","chunks":[]},{"id":"guanzi_ch-1_p-3_s-3","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-3","order":3,"canonicalText":"何謂四維？","chunks":[]},{"id":"guanzi_ch-1_p-3_s-4","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-3","order":4,"canonicalText":"一曰禮，二曰義，三曰廉，四曰恥。","chunks":[]},{"id":"guanzi_ch-1_p-3_s-5","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-3","order":5,"canonicalText":"禮不踰節，義不自進，廉不蔽惡，恥不從枉。","chunks":[]},{"id":"guanzi_ch-1_p-3_s-6","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-3","order":6,"canonicalText":"故不踰節則上位安，不自進則民無巧詐，不蔽惡則行自全，不從枉則邪事不生。","chunks":[]},{"id":"guanzi_ch-1_p-4_s-1","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-4","order":1,"canonicalText":"右四維。","chunks":[]},{"id":"guanzi_ch-1_p-4_s-2","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-4","order":2,"canonicalText":"守國之度，在張四維；","chunks":[]},{"id":"guanzi_ch-1_p-4_s-3","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-4","order":3,"canonicalText":"四維不張，國乃滅亡。","chunks":[]},{"id":"guanzi_ch-1_p-5_s-1","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-5","order":1,"canonicalText":"政之所興，在順民心。","chunks":[]},{"id":"guanzi_ch-1_p-5_s-2","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-5","order":2,"canonicalText":"政之所廢，在逆民心。","chunks":[]},{"id":"guanzi_ch-1_p-5_s-3","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-5","order":3,"canonicalText":"民惡憂勞，我佚樂之。","chunks":[]},{"id":"guanzi_ch-1_p-5_s-4","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-5","order":4,"canonicalText":"民惡貧賤，我富貴之，民惡危墜，我存安之。","chunks":[]},{"id":"guanzi_ch-1_p-5_s-5","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-5","order":5,"canonicalText":"民惡滅絕，我生育之。","chunks":[]},{"id":"guanzi_ch-1_p-5_s-6","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-5","order":6,"canonicalText":"能佚樂之，則民為之憂勞。","chunks":[]},{"id":"guanzi_ch-1_p-5_s-7","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-5","order":7,"canonicalText":"能富貴之，則民為之貧賤。","chunks":[]},{"id":"guanzi_ch-1_p-5_s-8","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-5","order":8,"canonicalText":"能存安之，則民為之危墜。","chunks":[]},{"id":"guanzi_ch-1_p-5_s-9","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-5","order":9,"canonicalText":"能生育之，則民為之滅絕。","chunks":[]},{"id":"guanzi_ch-1_p-5_s-10","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-5","order":10,"canonicalText":"故刑罰不足以畏其意，殺戮不足以服其心。","chunks":[]},{"id":"guanzi_ch-1_p-5_s-11","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-5","order":11,"canonicalText":"故刑罰繁而邪不勝，能順人心，則天下自服。","chunks":[]},{"id":"guanzi_ch-1_p-6_s-1","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-6","order":1,"canonicalText":"右四順。","chunks":[]},{"id":"guanzi_ch-1_p-6_s-2","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-6","order":2,"canonicalText":"順民之情，修政之本；","chunks":[]},{"id":"guanzi_ch-1_p-6_s-3","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-6","order":3,"canonicalText":"違民所欲，雖威必廢。","chunks":[]},{"id":"guanzi_ch-1_p-7_s-1","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-7","order":1,"canonicalText":"錯國於不傾之地，積於不涸之倉，藏於不竭之府，下令於流水之原，使民於不爭之官，明必死之路，開必生之門。","chunks":[]},{"id":"guanzi_ch-1_p-7_s-2","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-7","order":2,"canonicalText":"毋使民爭，則民自安；","chunks":[]},{"id":"guanzi_ch-1_p-7_s-3","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-7","order":3,"canonicalText":"毋使民巧，則民自實。","chunks":[]},{"id":"guanzi_ch-1_p-7_s-4","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-7","order":4,"canonicalText":"此之謂士經也。","chunks":[]},{"id":"guanzi_ch-1_p-8_s-1","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-8","order":1,"canonicalText":"右士經。","chunks":[]},{"id":"guanzi_ch-1_p-8_s-2","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-8","order":2,"canonicalText":"審立制度，安國固本；","chunks":[]},{"id":"guanzi_ch-1_p-8_s-3","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-8","order":3,"canonicalText":"明示死生，天下莫爭。","chunks":[]},{"id":"guanzi_ch-1_p-9_s-1","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-9","order":1,"canonicalText":"以家為鄉，鄉不可為也。","chunks":[]},{"id":"guanzi_ch-1_p-9_s-2","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-9","order":2,"canonicalText":"以鄉為國，國不可為也。","chunks":[]},{"id":"guanzi_ch-1_p-9_s-3","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-9","order":3,"canonicalText":"以國為天下，天下不可為也。","chunks":[]},{"id":"guanzi_ch-1_p-9_s-4","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-9","order":4,"canonicalText":"以家為家，以鄉為鄉，以國為國，以天下為天下。","chunks":[]},{"id":"guanzi_ch-1_p-9_s-5","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-9","order":5,"canonicalText":"審其分，明其職，各安其位，則六親固而五法行矣。","chunks":[]},{"id":"guanzi_ch-1_p-10_s-1","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-10","order":1,"canonicalText":"右六親五法。","chunks":[]},{"id":"guanzi_ch-1_p-10_s-2","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-10","order":2,"canonicalText":"修身齊家，各守其分；","chunks":[]},{"id":"guanzi_ch-1_p-10_s-3","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-10","order":3,"canonicalText":"治國平天下，法度明備。","chunks":[]},{"id":"guanzi_ch-1_p-10_s-4","chapterId":"guanzi_ch-1","passageId":"guanzi_ch-1_p-10","order":4,"canonicalText":"此牧民之終始也。","chunks":[]},{"id":"guanzi_ch-2_p-1_s-1","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-1","order":1,"canonicalText":"山高而不崩，則祈羊至矣；","chunks":[]},{"id":"guanzi_ch-2_p-1_s-2","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-1","order":2,"canonicalText":"淵深而不涸，則沈玉極矣，天不變其常，地不易其則，春秋冬夏，不更其節，古今一也。","chunks":[]},{"id":"guanzi_ch-2_p-1_s-3","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-1","order":3,"canonicalText":"故為人君者，守常而不妄，則萬民自化矣。","chunks":[]},{"id":"guanzi_ch-2_p-2_s-1","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-2","order":1,"canonicalText":"銜命者，君之尊也。","chunks":[]},{"id":"guanzi_ch-2_p-2_s-2","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-2","order":2,"canonicalText":"受辭者，名之鉉也。","chunks":[]},{"id":"guanzi_ch-2_p-2_s-3","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-2","order":3,"canonicalText":"上無事，則民自試。","chunks":[]},{"id":"guanzi_ch-2_p-2_s-4","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-2","order":4,"canonicalText":"抱蜀不言，而廟堂既修。","chunks":[]},{"id":"guanzi_ch-2_p-2_s-5","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-2","order":5,"canonicalText":"鴻鵠鏘鏘，唯民歌之。","chunks":[]},{"id":"guanzi_ch-2_p-2_s-6","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-2","order":6,"canonicalText":"明君垂拱，而天下自治。","chunks":[]},{"id":"guanzi_ch-2_p-3_s-1","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-3","order":1,"canonicalText":"平原之隰，奚有於高？","chunks":[]},{"id":"guanzi_ch-2_p-3_s-2","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-3","order":2,"canonicalText":"大山之隈，奚有於深？","chunks":[]},{"id":"guanzi_ch-2_p-3_s-3","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-3","order":3,"canonicalText":"訾讆之人，勿與任大。","chunks":[]},{"id":"guanzi_ch-2_p-3_s-4","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-3","order":4,"canonicalText":"譕臣者可以遠舉。","chunks":[]},{"id":"guanzi_ch-2_p-3_s-5","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-3","order":5,"canonicalText":"顧憂者可與致道。","chunks":[]},{"id":"guanzi_ch-2_p-3_s-6","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-3","order":6,"canonicalText":"任賢使能，必因其材也。","chunks":[]},{"id":"guanzi_ch-2_p-4_s-1","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-4","order":1,"canonicalText":"必得之事，不足賴也；","chunks":[]},{"id":"guanzi_ch-2_p-4_s-2","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-4","order":2,"canonicalText":"必諾之言，不足信也。","chunks":[]},{"id":"guanzi_ch-2_p-4_s-3","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-4","order":3,"canonicalText":"小謹者不大立，訾食者不肥體；","chunks":[]},{"id":"guanzi_ch-2_p-4_s-4","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-4","order":4,"canonicalText":"有無棄之言者，必參於天地。","chunks":[]},{"id":"guanzi_ch-2_p-4_s-5","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-4","order":5,"canonicalText":"察言觀行，不可不慎。","chunks":[]},{"id":"guanzi_ch-2_p-5_s-1","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-5","order":1,"canonicalText":"怠倦者不及，無廣者疑神，神者在內，不及者在門，在內者將假，在門者將待。","chunks":[]},{"id":"guanzi_ch-2_p-5_s-2","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-5","order":2,"canonicalText":"曙戒勿怠，後稚逢殃。","chunks":[]},{"id":"guanzi_ch-2_p-5_s-3","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-5","order":3,"canonicalText":"早作夜思，乃成大業。","chunks":[]},{"id":"guanzi_ch-2_p-6_s-1","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-6","order":1,"canonicalText":"道之所言者一也，而用之者異。","chunks":[]},{"id":"guanzi_ch-2_p-6_s-2","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-6","order":2,"canonicalText":"有聞道而好為家者，一家之人也；","chunks":[]},{"id":"guanzi_ch-2_p-6_s-3","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-6","order":3,"canonicalText":"有聞道而好為鄉者，一鄉之人也；","chunks":[]},{"id":"guanzi_ch-2_p-6_s-4","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-6","order":4,"canonicalText":"有聞道而好為國者，一國之人也；","chunks":[]},{"id":"guanzi_ch-2_p-6_s-5","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-6","order":5,"canonicalText":"有聞道而好為天下者，天下之人也。","chunks":[]},{"id":"guanzi_ch-2_p-6_s-6","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-6","order":6,"canonicalText":"器量不同，所成各殊。","chunks":[]},{"id":"guanzi_ch-2_p-7_s-1","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-7","order":1,"canonicalText":"生棟覆屋。","chunks":[]},{"id":"guanzi_ch-2_p-7_s-2","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-7","order":2,"canonicalText":"怨怒不及；","chunks":[]},{"id":"guanzi_ch-2_p-7_s-3","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-7","order":3,"canonicalText":"弱子下瓦，慈母操箠。","chunks":[]},{"id":"guanzi_ch-2_p-7_s-4","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-7","order":4,"canonicalText":"天道之極，遠者自親。","chunks":[]},{"id":"guanzi_ch-2_p-7_s-5","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-7","order":5,"canonicalText":"人事之起，近親造怨。","chunks":[]},{"id":"guanzi_ch-2_p-7_s-6","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-7","order":6,"canonicalText":"萬物之於人也，知其情者能御之。","chunks":[]},{"id":"guanzi_ch-2_p-8_s-1","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-8","order":1,"canonicalText":"烏鳥之狡，雖善不親。","chunks":[]},{"id":"guanzi_ch-2_p-8_s-2","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-8","order":2,"canonicalText":"不重之結，雖固必解；","chunks":[]},{"id":"guanzi_ch-2_p-8_s-3","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-8","order":3,"canonicalText":"道之用也，貴其重也。","chunks":[]},{"id":"guanzi_ch-2_p-8_s-4","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-8","order":4,"canonicalText":"毋與不可，毋彊不能，毋告不知；","chunks":[]},{"id":"guanzi_ch-2_p-8_s-5","chapterId":"guanzi_ch-2","passageId":"guanzi_ch-2_p-8","order":5,"canonicalText":"與不可，強不能，告不知，謂之勞而無功。","chunks":[]},{"id":"guanzi_ch-3_p-1_s-1","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-1","order":1,"canonicalText":"萬乘之國，兵不可以無主，土地博大，野不可以無吏，百姓殷眾，官不可以無長，操民之命，朝不可以無政。","chunks":[]},{"id":"guanzi_ch-3_p-1_s-2","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-1","order":2,"canonicalText":"政者，國之綱也。","chunks":[]},{"id":"guanzi_ch-3_p-3_s-1","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-3","order":1,"canonicalText":"地闢而國貧者，舟輿飾，臺榭廣也。","chunks":[]},{"id":"guanzi_ch-3_p-3_s-2","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-3","order":2,"canonicalText":"賞罰信而兵弱者，輕用眾，使民勞也。","chunks":[]},{"id":"guanzi_ch-3_p-3_s-3","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-3","order":3,"canonicalText":"舟車飾，臺榭廣，則賦斂厚，民怨上；","chunks":[]},{"id":"guanzi_ch-3_p-3_s-4","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-3","order":4,"canonicalText":"輕用眾，使民勞，則兵疲極，士不用。","chunks":[]},{"id":"guanzi_ch-3_p-3_s-5","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-3","order":5,"canonicalText":"故節用愛民，戰陣乃強。","chunks":[]},{"id":"guanzi_ch-3_p-4_s-1","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-4","order":1,"canonicalText":"欲為天下者，必重用其國，欲為其國者，必重用其民，欲為其民者，必重盡其民力。","chunks":[]},{"id":"guanzi_ch-3_p-4_s-2","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-4","order":2,"canonicalText":"無以畜之，則往而不可復也。","chunks":[]},{"id":"guanzi_ch-3_p-4_s-3","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-4","order":3,"canonicalText":"故養之以德，用之以時，蓄之以富，乃可長保天下。","chunks":[]},{"id":"guanzi_ch-3_p-5_s-1","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-5","order":1,"canonicalText":"見其可也，喜之有徵。","chunks":[]},{"id":"guanzi_ch-3_p-5_s-2","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-5","order":2,"canonicalText":"見其不可也，惡之有刑。","chunks":[]},{"id":"guanzi_ch-3_p-5_s-3","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-5","order":3,"canonicalText":"賞罰信於其所見，雖其所不見，其敢為之乎？","chunks":[]},{"id":"guanzi_ch-3_p-5_s-4","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-5","order":4,"canonicalText":"見其可也，喜之無徵；","chunks":[]},{"id":"guanzi_ch-3_p-5_s-5","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-5","order":5,"canonicalText":"見其不可也，惡之無刑。","chunks":[]},{"id":"guanzi_ch-3_p-5_s-6","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-5","order":6,"canonicalText":"賞罰不信於其所見，雖其所不見，其敢善之乎？","chunks":[]},{"id":"guanzi_ch-3_p-5_s-7","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-5","order":7,"canonicalText":"故賞罰之信，治亂之分也。","chunks":[]},{"id":"guanzi_ch-3_p-6_s-1","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-6","order":1,"canonicalText":"地之生財有時，民之用力有倦，而人君之慾無窮，以有時與有倦，養無窮之君，而度量不生於其間，則上下相疾，亂之原也。","chunks":[]},{"id":"guanzi_ch-3_p-6_s-2","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-6","order":2,"canonicalText":"故明君節慾以安民。","chunks":[]},{"id":"guanzi_ch-3_p-7_s-1","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-7","order":1,"canonicalText":"地之不闢者，非吾地也。","chunks":[]},{"id":"guanzi_ch-3_p-7_s-2","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-7","order":2,"canonicalText":"民之不牧者，非吾民也。","chunks":[]},{"id":"guanzi_ch-3_p-7_s-3","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-7","order":3,"canonicalText":"凡牧民者，以其所積者食之，不可不審也。","chunks":[]},{"id":"guanzi_ch-3_p-7_s-4","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-7","order":4,"canonicalText":"其積多者其國富，其積少者其國貧。","chunks":[]},{"id":"guanzi_ch-3_p-7_s-5","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-7","order":5,"canonicalText":"故務農積穀，富民之本也。","chunks":[]},{"id":"guanzi_ch-3_p-9_s-1","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-9","order":1,"canonicalText":"地之守在城，城之守在兵，兵之守在人，人之守在粟；","chunks":[]},{"id":"guanzi_ch-3_p-9_s-2","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-9","order":2,"canonicalText":"故地不闢，則城不固。","chunks":[]},{"id":"guanzi_ch-3_p-9_s-3","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-9","order":3,"canonicalText":"有身不治，奚待於人？","chunks":[]},{"id":"guanzi_ch-3_p-9_s-4","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-9","order":4,"canonicalText":"有國不治，奚待於天下？","chunks":[]},{"id":"guanzi_ch-3_p-9_s-5","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-9","order":5,"canonicalText":"故自修者為天下本。","chunks":[]},{"id":"guanzi_ch-3_p-10_s-1","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-10","order":1,"canonicalText":"商賈在朝，則貨財上流；","chunks":[]},{"id":"guanzi_ch-3_p-10_s-2","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-10","order":2,"canonicalText":"婦言人事，則賞罰不信；","chunks":[]},{"id":"guanzi_ch-3_p-10_s-3","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-10","order":3,"canonicalText":"男女無別，則民無廉恥；","chunks":[]},{"id":"guanzi_ch-3_p-10_s-4","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-10","order":4,"canonicalText":"貨財上流，賞罰不信，民無廉恥，此三者，國之大蠹也。","chunks":[]},{"id":"guanzi_ch-3_p-11_s-1","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-11","order":1,"canonicalText":"一年之計，莫如樹穀；","chunks":[]},{"id":"guanzi_ch-3_p-11_s-2","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-11","order":2,"canonicalText":"十年之計，莫如樹木；","chunks":[]},{"id":"guanzi_ch-3_p-11_s-3","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-11","order":3,"canonicalText":"終身之計，莫如樹人。","chunks":[]},{"id":"guanzi_ch-3_p-11_s-4","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-11","order":4,"canonicalText":"一樹一穫者，穀也；","chunks":[]},{"id":"guanzi_ch-3_p-11_s-5","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-11","order":5,"canonicalText":"一樹十穫者，木也；","chunks":[]},{"id":"guanzi_ch-3_p-11_s-6","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-11","order":6,"canonicalText":"一樹百穫者，人也。","chunks":[]},{"id":"guanzi_ch-3_p-11_s-7","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-11","order":7,"canonicalText":"我 daraus 樹之，天下利之。","chunks":[]},{"id":"guanzi_ch-3_p-11_s-8","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-11","order":8,"canonicalText":"此治國之大經也。","chunks":[]},{"id":"guanzi_ch-3_p-12_s-1","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-12","order":1,"canonicalText":"凡牧民者，使士無邪行，女無淫事。","chunks":[]},{"id":"guanzi_ch-3_p-12_s-2","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-12","order":2,"canonicalText":"士無邪行，教也。","chunks":[]},{"id":"guanzi_ch-3_p-12_s-3","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-12","order":3,"canonicalText":"女無淫事，訓也。","chunks":[]},{"id":"guanzi_ch-3_p-12_s-4","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-12","order":4,"canonicalText":"教訓成俗，而刑罰省，數也。","chunks":[]},{"id":"guanzi_ch-3_p-12_s-5","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-12","order":5,"canonicalText":"刑罰省而民自化，此所謂大治也。","chunks":[]},{"id":"guanzi_ch-3_p-13_s-1","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-13","order":1,"canonicalText":"凡牧民者，欲民之有義也；","chunks":[]},{"id":"guanzi_ch-3_p-13_s-2","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-13","order":2,"canonicalText":"欲民之有義，則小義不可不行；","chunks":[]},{"id":"guanzi_ch-3_p-13_s-3","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-13","order":3,"canonicalText":"小義不行於國，而求百姓之行大義，不可得也。","chunks":[]},{"id":"guanzi_ch-3_p-13_s-4","chapterId":"guanzi_ch-3","passageId":"guanzi_ch-3_p-13","order":4,"canonicalText":"故治國者，慎於微始。","chunks":[]},{"id":"guanzi_ch-4_p-2_s-1","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-2","order":1,"canonicalText":"君之所審者三：一曰德不當其位；","chunks":[]},{"id":"guanzi_ch-4_p-2_s-2","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-2","order":2,"canonicalText":"二曰功不當其祿；","chunks":[]},{"id":"guanzi_ch-4_p-2_s-3","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-2","order":3,"canonicalText":"三曰能不當其官；","chunks":[]},{"id":"guanzi_ch-4_p-2_s-4","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-2","order":4,"canonicalText":"此三本者，治亂之原也。","chunks":[]},{"id":"guanzi_ch-4_p-2_s-5","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-2","order":5,"canonicalText":"故德薄而位尊，功微而祿厚，無能而官大，此國之所以亂也。","chunks":[]},{"id":"guanzi_ch-4_p-2_s-6","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-2","order":6,"canonicalText":"故明君審其德，考其功，量其能，然後授之。","chunks":[]},{"id":"guanzi_ch-4_p-3_s-1","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-3","order":1,"canonicalText":"右三本。","chunks":[]},{"id":"guanzi_ch-4_p-3_s-2","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-3","order":2,"canonicalText":"審德、考功、量能，治國之大綱也。","chunks":[]},{"id":"guanzi_ch-4_p-4_s-1","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-4","order":1,"canonicalText":"君之所慎者四：一曰大德不至仁，不可以授國柄。","chunks":[]},{"id":"guanzi_ch-4_p-4_s-2","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-4","order":2,"canonicalText":"二曰見賢不能讓，不可與尊位。","chunks":[]},{"id":"guanzi_ch-4_p-4_s-3","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-4","order":3,"canonicalText":"三曰罰避親貴，不可使主刑。","chunks":[]},{"id":"guanzi_ch-4_p-4_s-4","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-4","order":4,"canonicalText":"四曰好戰貪利，不可使掌兵。","chunks":[]},{"id":"guanzi_ch-4_p-4_s-5","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-4","order":5,"canonicalText":"此四固者，安危之機也。","chunks":[]},{"id":"guanzi_ch-4_p-5_s-1","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-5","order":1,"canonicalText":"右四固。","chunks":[]},{"id":"guanzi_ch-4_p-5_s-2","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-5","order":2,"canonicalText":"慎選輔弼，安邦固本；","chunks":[]},{"id":"guanzi_ch-4_p-5_s-3","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-5","order":3,"canonicalText":"防微杜漸，社稷長存。","chunks":[]},{"id":"guanzi_ch-4_p-6_s-1","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-6","order":1,"canonicalText":"君之所務者五：一曰山澤不救於火，草木不植成，國之貧也。","chunks":[]},{"id":"guanzi_ch-4_p-6_s-2","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-6","order":2,"canonicalText":"二曰溝瀆不遂於隘，鄣水不安其藏，國之貧也。","chunks":[]},{"id":"guanzi_ch-4_p-6_s-3","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-6","order":3,"canonicalText":"三曰桑麻不植於野，六畜不蕃於家，國之貧也。","chunks":[]},{"id":"guanzi_ch-4_p-6_s-4","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-6","order":4,"canonicalText":"四曰田疇不闢於荒，五穀不殖於地，國之貧也。","chunks":[]},{"id":"guanzi_ch-4_p-6_s-5","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-6","order":5,"canonicalText":"五曰工匠不造其器，商賈不通其貨，國之貧也。","chunks":[]},{"id":"guanzi_ch-4_p-6_s-6","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-6","order":6,"canonicalText":"此五事者，富貧之原也。","chunks":[]},{"id":"guanzi_ch-4_p-7_s-1","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-7","order":1,"canonicalText":"右五事。","chunks":[]},{"id":"guanzi_ch-4_p-7_s-2","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-7","order":2,"canonicalText":"興修水利，務本農桑；","chunks":[]},{"id":"guanzi_ch-4_p-7_s-3","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-7","order":3,"canonicalText":"工商業通，富國之源。","chunks":[]},{"id":"guanzi_ch-4_p-8_s-1","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-8","order":1,"canonicalText":"分國以為五鄉，鄉為之師，分鄉以為五州，州為之長。","chunks":[]},{"id":"guanzi_ch-4_p-8_s-2","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-8","order":2,"canonicalText":"分州以為十里，裏為之尉。","chunks":[]},{"id":"guanzi_ch-4_p-8_s-3","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-8","order":3,"canonicalText":"分裏以為十遊，遊為之宗。","chunks":[]},{"id":"guanzi_ch-4_p-8_s-4","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-8","order":4,"canonicalText":"分遊以為十家，家為之長。","chunks":[]},{"id":"guanzi_ch-4_p-8_s-5","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-8","order":5,"canonicalText":"層層統攝，上下相維，則天下之民莫敢不順令矣。","chunks":[]},{"id":"guanzi_ch-4_p-9_s-1","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-9","order":1,"canonicalText":"孟春之朝，君自聽朝，論爵賞校官，終五日。","chunks":[]},{"id":"guanzi_ch-4_p-9_s-2","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-9","order":2,"canonicalText":"季冬之夕，君自聽朝，論罰罪刑殺，亦終五日。","chunks":[]},{"id":"guanzi_ch-4_p-9_s-3","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-9","order":3,"canonicalText":"正月之朔，百官受令於朝，修法以待政。","chunks":[]},{"id":"guanzi_ch-4_p-9_s-4","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-9","order":4,"canonicalText":"此首憲之法也。","chunks":[]},{"id":"guanzi_ch-4_p-10_s-1","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-10","order":1,"canonicalText":"右首憲。","chunks":[]},{"id":"guanzi_ch-4_p-10_s-2","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-10","order":2,"canonicalText":"孟春行賞，季冬決刑；","chunks":[]},{"id":"guanzi_ch-4_p-10_s-3","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-10","order":3,"canonicalText":"歲首布憲，綱紀嚴明。","chunks":[]},{"id":"guanzi_ch-4_p-12_s-1","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-12","order":1,"canonicalText":"右首事。","chunks":[]},{"id":"guanzi_ch-4_p-12_s-2","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-12","order":2,"canonicalText":"舉事先令，賞罰預明；","chunks":[]},{"id":"guanzi_ch-4_p-12_s-3","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-12","order":3,"canonicalText":"計功覈實，程序嚴整。","chunks":[]},{"id":"guanzi_ch-4_p-13_s-1","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-13","order":1,"canonicalText":"修火憲，敬山澤，林藪積草，夫財之所出，以時禁發焉。","chunks":[]},{"id":"guanzi_ch-4_p-13_s-2","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-13","order":2,"canonicalText":"使民足於宮室之用，薪蒸之所積，虞師之事也。","chunks":[]},{"id":"guanzi_ch-4_p-13_s-3","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-13","order":3,"canonicalText":"省官減冗，各司其職，則國事修矣。","chunks":[]},{"id":"guanzi_ch-4_p-14_s-1","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-14","order":1,"canonicalText":"右省官。","chunks":[]},{"id":"guanzi_ch-4_p-14_s-2","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-14","order":2,"canonicalText":"保護生態，時禁時發；","chunks":[]},{"id":"guanzi_ch-4_p-14_s-3","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-14","order":3,"canonicalText":"精簡機構，政令暢通。","chunks":[]},{"id":"guanzi_ch-4_p-15_s-1","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-15","order":1,"canonicalText":"度爵而制服，量祿而用財，飲食有量，衣服有制，宮室有度，六畜人徒有數，舟車陳器有禁，修生則有賞，奢靡則有刑。","chunks":[]},{"id":"guanzi_ch-4_p-15_s-2","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-15","order":2,"canonicalText":"此服制之大法也。","chunks":[]},{"id":"guanzi_ch-4_p-16_s-1","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-16","order":1,"canonicalText":"右服制。","chunks":[]},{"id":"guanzi_ch-4_p-16_s-2","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-16","order":2,"canonicalText":"量入為出，節儉尚質；","chunks":[]},{"id":"guanzi_ch-4_p-16_s-3","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-16","order":3,"canonicalText":"明定法度，禁絕奢靡。","chunks":[]},{"id":"guanzi_ch-4_p-17_s-1","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-17","order":1,"canonicalText":"寢兵之說勝，則險阻不守；","chunks":[]},{"id":"guanzi_ch-4_p-17_s-2","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-17","order":2,"canonicalText":"兼愛之說勝，則士卒不戰。","chunks":[]},{"id":"guanzi_ch-4_p-17_s-3","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-17","order":3,"canonicalText":"全生之說勝，則廉恥不立。","chunks":[]},{"id":"guanzi_ch-4_p-17_s-4","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-17","order":4,"canonicalText":"私議自貴之說勝，則法令不行。","chunks":[]},{"id":"guanzi_ch-4_p-17_s-5","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-17","order":5,"canonicalText":"此九敗之原也，明君審禁之。","chunks":[]},{"id":"guanzi_ch-4_p-18_s-1","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-18","order":1,"canonicalText":"右九敗。","chunks":[]},{"id":"guanzi_ch-4_p-18_s-2","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-18","order":2,"canonicalText":"辨明邪正，固守法度；","chunks":[]},{"id":"guanzi_ch-4_p-18_s-3","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-18","order":3,"canonicalText":"嚴防偏說，國家永固。","chunks":[]},{"id":"guanzi_ch-4_p-19_s-1","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-19","order":1,"canonicalText":"期而致，使而往，百姓捨己以上為心者，教之所期也。","chunks":[]},{"id":"guanzi_ch-4_p-19_s-2","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-19","order":2,"canonicalText":"始於不足見，終於不可及，一人服之，萬人從之，此七觀之大法也。","chunks":[]},{"id":"guanzi_ch-4_p-20_s-1","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-20","order":1,"canonicalText":"右七觀。","chunks":[]},{"id":"guanzi_ch-4_p-20_s-2","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-20","order":2,"canonicalText":"化民成俗，一人唱而萬人和；","chunks":[]},{"id":"guanzi_ch-4_p-20_s-3","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-20","order":3,"canonicalText":"德法兼施，天下大治。","chunks":[]},{"id":"guanzi_ch-4_p-20_s-4","chapterId":"guanzi_ch-4","passageId":"guanzi_ch-4_p-20","order":4,"canonicalText":"此立政之終始也。","chunks":[]}]}');export{a as default};
